let juiceSnapshot=null,juiceAudio=null,juiceLastTone=0,toastTimer=null;
const juiceMotion=()=>prefs.motion&&!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
function juiceAnimate(el,frames,duration=240){if(!el?.animate||!juiceMotion())return;el.getAnimations?.().forEach(a=>a.cancel());el.animate(frames,{duration,easing:'cubic-bezier(.2,.8,.2,1)'});}
function juiceTone(kind='click'){
 if(!prefs.sound)return;const now=Date.now();if(kind==='click'&&now-juiceLastTone<90)return;juiceLastTone=now;
 try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;juiceAudio??=new C();if(juiceAudio.state==='suspended')juiceAudio.resume().catch(()=>{});
 const notes=kind==='error'?[220,174]:kind==='win'?[392,494,587,784]:kind==='click'?[440]:[520,780];
 notes.forEach((frequency,i)=>{const o=juiceAudio.createOscillator(),g=juiceAudio.createGain(),at=juiceAudio.currentTime+i*.065;o.type='sine';o.frequency.value=frequency;g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(kind==='click'?.018:.035,at+.008);g.gain.exponentialRampToValueAtTime(.001,at+.13);o.connect(g);g.connect(juiceAudio.destination);o.start(at);o.stop(at+.14);o.onended=()=>{o.disconnect();g.disconnect();};});}catch{}
}
function juiceBurst(target){if(!target||!juiceMotion()||!document.createElement)return;target.classList.add('juice-celebration');for(let i=0;i<18;i++){const dot=document.createElement('i');dot.className='juice-confetti';dot.setAttribute('aria-hidden','true');dot.style.setProperty('--jx',Math.round(Math.cos(i*Math.PI/9)*(70+i%4*18))+'px');dot.style.setProperty('--jy',Math.round(Math.sin(i*Math.PI/9)*90+65)+'px');dot.style.setProperty('--jr',i*47+'deg');dot.style.animationDelay=(i%3)*35+'ms';target.appendChild(dot);dot.addEventListener('animationend',()=>dot.remove(),{once:true});setTimeout(()=>dot.remove(),1500);}}
function juiceAfterRender(){
 const tm=S?.teams?.find(x=>x.id===S.user),current={game:S?.id,user:S?.user,route,tabs:[view,profileTab,statScope,teamPreferences,teamRotation].join(':'),day:S?S.season+':'+S.day+':'+(S.offseason?.stage||''):'',positions:JSON.stringify(tm?.positions||{}),order:JSON.stringify(tm?.order||[]),moment:moment?moment.kind+':'+moment.event?.inning+':'+moment.event?.half+':'+moment.event?.score?.join('-'):'',award:route==='offseason'?S?.season+':'+S?.offseason?.stage+':'+(awardCursor[S.id+':'+S.season+':'+S.user]||0):'',score:document.querySelector('.match-board .score')?.textContent};
 const old=juiceSnapshot;juiceSnapshot=current;if(!old)return;
 if(old.route!==current.route||old.tabs!==current.tabs)juiceAnimate(document.querySelector('main'),[{opacity:.4,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],180);
 if(old.game===current.game&&old.user===current.user){
 if(old.day!==current.day){juiceAnimate(document.querySelector('.context'),[{opacity:.35,transform:'translateY(-8px)'},{opacity:1,transform:'translateY(0)'}],320);juiceTone('ok');}
 else if(old.positions!==current.positions||old.order!==current.order){const before=JSON.parse(old.positions),after=JSON.parse(current.positions),beforeOrder=JSON.parse(old.order),afterOrder=JSON.parse(current.order),changed=new Set([...Object.keys(after).filter(k=>before[k]!==after[k]).flatMap(k=>[before[k],after[k]]),...afterOrder.filter((id,i)=>beforeOrder[i]!==id)]);for(const el of document.querySelectorAll('[data-move-id]'))if(changed.has(el.dataset.moveId))juiceAnimate(el,[{boxShadow:'0 0 0 2px #f0c365',filter:'brightness(1.25)'},{boxShadow:'0 0 0 0px transparent',filter:'brightness(1)'}],650);if(route==='team')notify(tr('Formation défensive et ordre de frappe à jour.','Defense and batting order updated.','Defensa y orden de bateo actualizados.'));}
 if(old.score!==current.score&&current.score)juiceAnimate(document.querySelector('.match-board .score'),[{transform:'scale(1)'},{transform:'scale(1.12)',offset:.4},{transform:'scale(1)'}],400);
 }
 if(current.moment&&old.moment!==current.moment&&['home-run','grand-slam','victory'].includes(moment.kind)){juiceBurst(document.querySelector('.moment-ribbon'));juiceTone('win');}
 if(current.award&&current.award!==old.award){juiceBurst(document.querySelector('.award-presentation'));juiceTone('win');}
}
function notify(message,error=false){let el=document.querySelector('#toast');el.textContent=message;el.className=error?'show error':'show';juiceTone(error?'error':'ok');juiceAnimate(el,error?[{transform:'translateX(0)'},{transform:'translateX(-3px)'},{transform:'translateX(3px)'},{transform:'translateX(0)'}]:[{opacity:0,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],220);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',5000);}
