function persist(){if(S?.online)return ON.host?ON.save(ON.state).then(()=>true):Promise.resolve(true);if(!S)return Promise.resolve(true);const snapshot=E.clone(S);pendingSaves++;saveQueue=saveQueue.then(async()=>{try{await Store.save(snapshot);savedGames=await Store.list();saveFailed=false;pendingSaves--;let status=document.querySelector('#save-status');if(status){status.classList.remove('unsaved');status.textContent=pendingSaves?t('saving'):t('saved');}return true;}catch(e){pendingSaves--;saveFailed=true;notify(t('save_failed'),true);let status=document.querySelector('#save-status');if(status){status.classList.add('unsaved');status.textContent=t('save_failed');}return false;}});return saveQueue;}

