function sidebarNavigation(){
 const ongoing=S.draft?'draft':S.offseason?'offseason':S.playoffs&&!S.playoffs.winner?'playoffs':null;
 const groups=navGroups.map(group=>`<section class="nav-group nav-group-${group.id}" aria-label="${group.label()}">${group.id==='primary'?'':`<h2 class="nav-group-title">${group.label()}</h2>`}${group.keys.map(key=>{
 const label=key==='favorites'?tr('Favoris','Favorites','Favoritos'):key==='rules'?tr('Wiki & règles','Wiki & rules','Wiki y reglas'):t(key);
 return go(`<span class="nav-icon" aria-hidden="true">${navIcon(key)}</span><span class="nav-label">${label}</span>${key==='trades'&&S.trades.length?badge(S.trades.length):''}${key===ongoing?`<span class="nav-ongoing">${tr('En cours','In progress','En curso')}</span>`:''}`,key,route===key?'aria-current="page"':'',route===key?'active':'');
 }).join('')}</section>`);
 return groups[0]+'<div class="nav-secondary">'+groups.slice(1).join('')+'</div>';
}

function shell(content){const backButtons=[...content.matchAll(/<button\b[^>]*>[\s\S]*?<\/button>/g)].filter(m=>m[0].includes(`>${t('back')}</button>`));const back=backButtons[0]?.[0]||(!['menu','dashboard'].includes(route)?go(t('back'),S?'dashboard':'menu'):'');for(const m of backButtons)content=content.replace(m[0],'');const theme=themeTokens(S?viewedLogo(S,route,params,dataSource(),previousProfile):route==='new'?selectedLogo:null);return `<style id="team-theme">${theme?':root{'+theme+'}':''}</style><header class="masthead"><a href="#" data-action="nav" data-to="${S?'dashboard':'menu'}" class="wordmark">SLIMBALL<span>MANAGER</span></a><div class="edition">CLUB RÉTRO <span>•</span> ${S?teamMark(E.team(S)):tr('LA LIGUE VOUS ATTEND','THE LEAGUE AWAITS','LA LIGA TE ESPERA')}</div><div class="languages">${['fr','en','es'].map(l=>btn(l.toUpperCase(),'language',`data-lang="${l}"`,l===lang?'selected':'')).join('')}</div></header><div class="layout ${S?'':'no-sidebar'}">${S?`<aside class="sidebar"><nav aria-label="${t('team')}">${sidebarNavigation()}</nav><div class="sidebar-foot">${btn(t('quit'),'quit','','quiet')}<small id="save-status" role="status" aria-live="polite">${saveFailed?t('save_failed'):pendingSaves?t('saving'):t('saved')}</small><span class="version">v1.23.0 · ${S?.online?'EN LIGNE':'SOLO'}</span></div></aside>`:''}<main id="main" class="page-${route}">${S?`<div class="context"><span>${archiveId?t('season')+' '+archiveId+' · '+t('archive_note'):dateLabel()}</span><span>${S.mode==='career'?t('career'):t('free_mode')}</span></div>`:''}${back?`<div class="page-back">${back}</div>`:''}${onlinePanel()}${tutorialHTML()}${content}</main></div><footer class="footer">SLIMBALL MANAGER <span>CLUB RÉTRO · 2026</span></footer>`;}
const PARKS={
 wolf:['Parc du Village','Village Park','Parque del Pueblo'],hawk:['Parc des Sommets','Summit Park','Parque de las Cumbres'],bison:['Parc des Blés d’or','Golden Fields Park','Parque de los Trigales'],shark:['Parc du Havre','Harbour Park','Parque del Puerto'],lynx:['Parc des Rochers','Granite Park','Parque de las Rocas'],fox:['Parc des Ateliers','Milltown Park','Parque de los Talleres'],horse:['Parc des Prairies','Meadow Park','Parque de las Praderas'],owl:['Parc de la Clairière','Woodland Park','Parque del Claro'],bear:['Parc du Grand Lac','Great Lake Park','Parque del Gran Lago'],wasp:['Parc des Vergers','Orchard Park','Parque de los Huertos']};
const parkId=tm=>E.logoById(tm?.logo)?.id||'wolf';
const parkName=tm=>PARKS[parkId(tm)][['fr','en','es'].indexOf(lang)];
// Landmarks measured on each illustration: first, second, third, mound and home.
const parkLandmarks={wolf:[75.9,61.3,50,51.3,24.1,61.3,62.2,85.6],hawk:[75.5,62.1,50,51.4,24.5,62.1,61.5,81.4],bison:[75.1,58.6,50,48.8,24.9,58.6,61.1,82.8],shark:[74.5,58.2,50,47.4,25.5,58.2,59.6,83.2],lynx:[73.3,57.5,50,48.7,26.7,57.5,59.1,78.7],fox:[74.5,58.5,50,48.6,25.5,58.5,59.5,82.3],horse:[76.4,57.8,50,46.4,23.4,57.8,58.8,81.4],owl:[72.1,58.1,50,48.3,27.9,58.1,59.1,77.7],bear:[74.1,59.2,50,49.6,25.7,59.2,60.9,81.4],wasp:[74.2,59.1,50,47.9,25.7,59.1,59.7,82.0]};
const parkStyle=tm=>{const id=parkId(tm),a=parkLandmarks[id];return `--park-image:url('./assets/parks/${id}.webp');--b1-x:${a[0]}%;--b1-y:${a[1]}%;--b2-x:${a[2]}%;--b2-y:${a[3]}%;--b3-x:${a[4]}%;--b3-y:${a[5]}%;--mound-y:${a[6]}%;--home-y:${a[7]}%`;};
const roleArt=(pose='bat',p=null,owner=undefined,src=dataSource())=>{if(!p)return '';const a=E.appearance(src,p,owner);return `<span class="role-art personalized role-${pose}" aria-hidden="true">${E.actionSvg(a.portraitId,a.logo,pose)}</span>`;};
function parkView(tm,cls='',overlay=''){return `<figure class="park-view ${cls}" style="${parkStyle(tm)}"><img class="park-landscape" src="./assets/parks/${parkId(tm)}.webp" alt="${esc(parkName(tm)+' · '+tm.name)}" decoding="async"><figcaption>${logoImage(tm.logo)}<span><small>${tr('TERRAIN LOCAL','HOME FIELD','CAMPO LOCAL')}</small><strong>${esc(parkName(tm))}</strong></span></figcaption>${overlay}</figure>`;}
const fieldSlots={P:[50,67],C:[50,90],GO:[29,63],GE:[71,63],FO:[31,42],FE:[69,42]};
function lineupPark(src,tm,canMove){return parkView(tm,'lineup-park',E.POS.map(pos=>{const p=src.players[tm.positions[pos]];if(!p)return '';const a=parkLandmarks[parkId(tm)],[x,y]=pos==='P'?[50,a[6]]:pos==='C'?[50,a[7]+4]:fieldSlots[pos];return `<div class="field-slot" style="left:${x}%;top:${y}%" ${moveAttrs(p.id,'defense',canMove)}>${canMove?moveHandle(p,true):playerLink(p,'',true,tm)}<span class="slot-label"><b>${pos}</b> ${canMove?playerLink(p,'',false,tm):''}</span>${lineupSkills(p,true)}</div>`;}).join(''));}
function clubCards(){if(!S)return '';return `<div class="park-gallery">${S.teams.map(tm=>`<article>${parkView(tm)}${btn(teamMark(tm),'view-team',`data-id="${tm.id}"`,'text-button')}<span class="muted">${tm.w} ${t('wins')} · ${tm.l} ${t('losses')}</span></article>`).join('')}</div>`;}
function featuredPlayers(tm){
 const pool=tm.roster.map(id=>S.players[id]),used=new Set(),pick=keys=>{const p=pool.filter(p=>!used.has(p.id)).sort((a,b)=>keys.reduce((v,k)=>v+b.base[k]-a.base[k],0)||a.id.localeCompare(b.id))[0];if(p)used.add(p.id);return p;};
 const pitcher=pick(['throw']),batter=pick(['contact','power']),fielder=pick(['catch','speed']);
 return `<div class="featured-players">${[batter,pitcher,fielder].map((p,i)=>p?`<article class="action-card" data-feature="${['batter','pitcher','fielder'][i]}" style="${parkStyle(tm)}"><div class="action-illustration">${roleArt(['bat','pitch','catch'][i],p,tm)}</div><div class="action-card-info"><strong class="feature-role">${[tr('Frappeur','Batter','Bateador'),tr('Lanceur','Pitcher','Lanzador'),tr('Défenseur','Fielder','Defensor')][i]}</strong>${playerLink(p,'',false,tm)}<span>${badge(p.grade)} ${E.position(tm,p.id)} · ${p.age} ${tr('ans','years','años')}</span><small>${i===0?`${statIcon('contact')}Con ${p.base.contact} + ${statIcon('power')}Pow ${p.base.power} = ${p.base.contact+p.base.power}`:i===1?`${statIcon('throw')}Throw ${p.base.throw}`:`${statIcon('catch')}Catch ${p.base.catch} + ${statIcon('speed')}Speed ${p.base.speed} = ${p.base.catch+p.base.speed}`}</small><small>${t('energy')} ${p.energy}</small></div></article>`:'').join('')}</div>`;
}
function title(text,actions=''){return `<div class="page-title"><h1>${text}</h1><div class="actions">${actions}</div></div>`;}
function menu(){let saves=savedGames;return `<div class="start-screen"><div class="start-art"><div class="start-logo">SLIMBALL<span>MANAGER</span><small>CLUB RÉTRO</small></div></div><section class="start-card"><span class="eyebrow">${tr('VOTRE PROCHAINE SAISON','YOUR NEXT SEASON','TU PRÓXIMA TEMPORADA')}</span><h1>${tr('À vous de jouer.','Your call.','Tu turno.')}</h1><div class="start-actions">${saves[0]&&!saves[0].corrupt?btn(`${t('continue')}<small>${esc(saves[0].name)} · ${t('season')} ${saves[0].season}</small>`,'load',`data-id="${saves[0].id}"`,'primary'):''}${go(t('new'),'new','','outline')}${btn('Jouer en ligne','online-menu','','primary')}${go(t('saves'),'saves')}${go(t('rules'),'rules')}</div><p class="muted">${tr('6 équipes. 33 matchs. Une place au sommet.','6 teams. 33 games. One champion.','6 equipos. 33 partidos. Un campeón.')}</p></section></div>`;}
// Tutorial belongs to the solo save; online state never reads or writes it.
function tutorialState(){return S&&!S.online&&S.tutorial?.version===1?S.tutorial:null;}
function tutorialDone(id){const state=tutorialState();if(!state?.enabled)return false;state.done=Array.isArray(state.done)?state.done:[];if(state.done.includes(id))return false;state.done.push(id);return true;}
function tutorialSync(){
 const state=tutorialState();if(!state?.enabled)return;
 let dirty=false;const done=id=>{dirty=tutorialDone(id)||dirty;};
 if(!S.draft||S.draft.kind!=='initial')done('draft');
 else if(E.team(S).roster.length)done('draft');
 if(route==='profile')done('inspect');
 if(route==='team'&&!archiveId&&(params.id||S.user)===S.user)done('dashboard');
 if(route==='team'&&teamRotation)done('rotation-open');
 const played=S.schedule.some(m=>m.result&&(m.home===S.user||m.away===S.user));
 if(played){done('before');done('dashboard');}
 if(dirty)persist();
}
function tutorialTip(){
 const state=tutorialState();if(!state?.enabled||archiveId)return null;
 const done=new Set(Array.isArray(state.done)?state.done:[]),initial=S.draft?.kind==='initial';
 const played=S.schedule.some(m=>m.result&&(m.home===S.user||m.away===S.user));
 const own=(params.id||S.user)===S.user;
 // Ordered within each context, so skipping a screen never blocks later advice.
 const tips=[
 ['draft',route==='draft'&&initial,['Votre premier repêchage','Your first draft','Tu primer draft'],['Choisissez 8 joueurs. L’ordre est tiré au hasard et s’inverse à chaque ronde. Avancez jusqu’à votre tour, puis choisissez librement votre première recrue.','Choose 8 players. The random draft order reverses each round. Advance to your turn, then choose your first player.','Elige 8 jugadores. El orden aleatorio se invierte en cada ronda. Avanza hasta tu turno y elige tu primer jugador.'],'[data-action="draft-until-user"], [data-action="choose"]'],
 ['inspect',route==='draft'&&initial,['Comparer les joueurs','Compare players','Comparar jugadores'],['Cliquez sur un nom pour ouvrir sa fiche. CON et POW servent à frapper; THR au lancer; CAT et SPE à défendre. Les ⓘ expliquent chaque statistique.','Click a name to open a profile. CON and POW help batting, THR pitching, CAT and SPE fielding. The ⓘ controls explain each statistic.','Abre una ficha pulsando un nombre. CON y POW ayudan al bateo, THR al lanzamiento, CAT y SPE a la defensa. ⓘ explica cada estadística.'],'[data-action="profile"]'],
 ['balance',route==='draft'&&initial,['Construire un effectif équilibré','Build a balanced roster','Construir una plantilla equilibrada'],['Prévoyez de bons frappeurs, des défenseurs et plusieurs lanceurs avec un bon THR. Vous aurez 6 titulaires et 2 remplaçants. Le talent indique le niveau initial; les attributs actuels restent essentiels.','Draft hitters, fielders and several pitchers with good THR. You will have 6 starters and 2 substitutes. Talent is a starting grade; current skills matter.','Busca bateadores, defensores y varios lanzadores con buen THR. Tendrás 6 titulares y 2 suplentes. El talento es inicial; los atributos actuales importan.'],'[data-action="choose"]'],
 ['profile',route==='profile',['Lire une fiche','Read a player profile','Leer una ficha'],['Comparez les attributs, l’énergie et les résultats. La forme de carrière décrit l’évolution avec l’âge; le talent reste fixe. Le wiki et les ⓘ donnent les détails. Revenez ensuite à votre sélection.','Compare skills, energy and results. Career form describes age-related development; talent stays fixed. Find details in the wiki and ⓘ, then return to your selection.','Compara atributos, energía y resultados. La forma de carrera describe la evolución con la edad; el talento es fijo. Consulta la wiki y ⓘ y vuelve a tu selección.'],'[data-action="profile-back"]'],
 ['lineup',route==='team'&&own&&!initial&&!teamRotation&&!teamPreferences,['Composer votre équipe','Set your lineup','Preparar tu alineación'],['Glissez un portrait sur un autre, ou sélectionnez deux portraits, pour échanger des joueurs. Le banc permet de faire reposer un titulaire. « Alignement automatique » prépare une composition pour vous.','Drag one portrait onto another, or select two portraits, to swap players. Use the bench to rest starters. Auto lineup prepares a lineup for you.','Arrastra un retrato sobre otro, o selecciona dos retratos, para intercambiar jugadores. Usa el banquillo para descansar. La alineación automática te ayuda.'],'[data-action="auto-align"]'],
 ['order',route==='team'&&own&&!initial&&!teamRotation&&!teamPreferences,['L’ordre de frappe','Batting order','Orden de bateo'],['Les six titulaires frappent dans l’ordre de cette liste. Glissez les joueurs pour changer cet ordre. CON + POW aide à repérer vos meilleurs frappeurs; modifier cet ordre ne change pas leurs positions défensives.','The six starters bat in this list’s order. Drag players to reorder them. CON + POW helps identify your strongest hitters; reordering does not change fielding positions.','Los seis titulares batean en este orden. Arrastra jugadores para cambiarlo. CON + POW ayuda a identificar buenos bateadores; el orden no cambia sus posiciones defensivas.'],'.batting-order'],
 ['rotation-open',route==='team'&&own&&!initial&&!teamRotation,['Préparer vos lanceurs','Prepare your pitchers','Preparar tus lanzadores'],['Ouvrez « Rotation des lanceurs ». Une rotation existe déjà : vous pouvez la garder ou choisir vos 2 à 4 lanceurs et leur ordre.','Open Pitching rotation. A rotation is already prepared: keep it or choose 2–4 pitchers and their order.','Abre Rotación de lanzadores. Ya hay una rotación: consérvala o elige de 2 a 4 lanzadores y su orden.'],'[data-action="rotation-tab"]'],
 ['rotation',route==='team'&&own&&teamRotation&&!initial,['Rotation et énergie','Rotation and energy','Rotación y energía'],['L’alignement automatique utilise le prochain lanceur. Sous 60 d’énergie, il passe au suivant; si tous sont sous 60, il choisit le plus reposé. Un lanceur peut aussi jouer à une autre position. Enregistrez vos choix si vous les modifiez.','Auto lineup uses the next pitcher. Below 60 energy, it tries the next; if all are below 60, it chooses the most rested. Pitchers can play other positions. Save any changes.','La alineación automática usa el siguiente lanzador. Bajo 60 de energía pasa al siguiente; si todos están bajo 60, elige al más descansado. También pueden jugar en otras posiciones. Guarda los cambios.'],'#rotation-form'],
 ['dashboard',route==='dashboard'&&!initial&&!played,['Votre journée de gestion','Your management day','Tu jornada de gestión'],['Le tableau de bord montre votre prochain match et les actions du jour. Ouvrez la gestion d’équipe pour vérifier votre alignement; le calendrier indique quand vous jouez.','The dashboard shows your next game and today’s actions. Open team management to check the lineup; the calendar shows your games.','El panel muestra tu próximo partido y las acciones del día. Abre la gestión del equipo para revisar la alineación; el calendario muestra los partidos.'],'[data-to="team"]'],
 ['before',['dashboard','prematch'].includes(route)&&!initial&&!played,['Votre premier match','Your first game','Tu primer partido'],['Vérifiez l’énergie et l’alignement. Avancez les jours jusqu’au prochain match, puis regardez-le ou simulez-le. La simulation utilise les mêmes règles; vous pouvez aussi simuler une période.','Check energy and the lineup. Advance to the next game, then watch or simulate it. Simulation uses the same rules; you can also simulate a period.','Revisa energía y alineación. Avanza hasta el partido y míralo o simúlalo. La simulación usa las mismas reglas; también puedes simular un período.'],'[data-action="simulate"], [data-action="pregame-watch"], [data-action="next"]'],
 ['after',['dashboard','match'].includes(route)&&played,['Après le match','After the game','Después del partido'],['Consultez le résumé : score par manche et statistiques des joueurs. Surveillez l’énergie avant le prochain match; le banc et les jours sans match permettent de récupérer. Vous pouvez maintenant gérer vos journées; d’autres conseils apparaîtront à la découverte des menus.','Read the summary for inning scores and player statistics. Check energy before the next game; bench time and days off restore it. You can now manage your days; other menus will offer tips when first visited.','Consulta el resumen: marcador por entrada y estadísticas. Revisa la energía; el banquillo y los días libres permiten recuperarla. Ya puedes gestionar tus jornadas; otros menús ofrecerán consejos al descubrirlos.'],'.match-board, [data-action="match-open"]'],
 ['calendar',route==='calendar',['Suivre le calendrier','Follow the schedule','Seguir el calendario'],['Repérez les matchs et les jours de repos. Les logos identifient les adversaires; ouvrez un résultat pour revoir son résumé.','Find games and rest days. Logos identify opponents; open a result to read its summary.','Localiza partidos y días libres. Los logos identifican rivales; abre un resultado para ver su resumen.'],''],
 ['trades',['trades','trade-new'].includes(route),['Négocier un échange','Negotiate a trade','Negociar un intercambio'],['Proposez des joueurs et, au besoin, des points. La valeur d’échange aide à comparer, mais l’IA considère aussi ses besoins. Une proposition peut être refusée ou recevoir une contre-offre; suivez son statut ici.','Offer players and, if needed, points. Trade value helps compare players, but AI also considers its needs. Offers may be rejected or countered; follow their status here.','Ofrece jugadores y, si hace falta, puntos. El valor ayuda a comparar, pero la IA considera sus necesidades. Puede rechazar o contraofertar; sigue el estado aquí.'],''],
 ['free',route==='free',['Recruter un agent libre','Recruit a free agent','Fichar un agente libre'],['Comparez les joueurs sans équipe avec votre effectif. À 8 joueurs, une signature demande de choisir un joueur à libérer : vérifiez bien ce remplacement avant de confirmer.','Compare unsigned players with your roster. At 8 players, signing requires releasing a player: review that replacement before confirming.','Compara jugadores libres con tu plantilla. Con 8 jugadores, fichar exige liberar a uno: revisa el reemplazo antes de confirmar.'],'[data-action="sign"]'],
 ['progression',['league','season','leaders'].includes(route),['Suivre la progression','Track development','Seguir la progresión'],['Comparez les statistiques et l’évolution des attributs des joueurs de la ligue. Jouer favorise la progression; l’âge et la forme de carrière influencent aussi leur évolution.','Compare league player results and skill changes. Playing supports development; age and career form also influence it.','Compara resultados y cambios de atributos en la liga. Jugar favorece la progresión; edad y forma de carrera también influyen.'],''],
 ['playoffs',route==='playoffs',['Les séries éliminatoires','The playoffs','Las eliminatorias'],['La saison régulière détermine la qualification. Suivez les séries et leurs résultats ici; préparez vos lanceurs et profitez des journées de repos.','The regular season determines qualification. Follow series and results here; prepare pitchers and use rest days.','La temporada regular determina la clasificación. Sigue las series y resultados; prepara lanzadores y aprovecha el descanso.'],''],
 ['offseason',route==='offseason',['Préparer la saison suivante','Prepare next season','Preparar la siguiente temporada'],['L’entre-saison présente les récompenses, le développement et les départs à la retraite. Consultez chaque bilan avant d’avancer; vous pourrez ensuite renforcer votre équipe au repêchage.','The offseason presents awards, development and retirements. Review each report before advancing; then strengthen your roster in the draft.','La pretemporada presenta premios, desarrollo y retiros. Revisa cada informe antes de avanzar y refuerza tu equipo en el draft.'],''],
 ['renewal',route==='draft'&&!initial,['Le repêchage entre saisons','Between-season draft','Draft entre temporadas'],['Choisissez selon les besoins de votre équipe. À effectif complet, il faut remplacer un joueur. Vous pouvez passer votre tour, et même ne recruter personne pendant ce repêchage.','Draft for your team’s needs. With a full roster, replace a player. You can skip a turn or make no selections in this draft.','Elige según las necesidades del equipo. Con plantilla completa debes reemplazar a alguien. Puedes pasar turno o no elegir a nadie.'],'[data-action="draft-skip"]']
 ];
 return tips.find(([id,eligible])=>eligible&&!done.has(id))||null;
}
function tutorialHTML(){
 const state=tutorialState();if(!state?.enabled)return '';
 const tip=tutorialTip();if(!tip)return '';
 if(state.minimized)return `<div class="tutorial-collapsed">${btn(tr('Afficher le conseil','Show tip','Mostrar consejo'),'tutorial-expand')}</div>`;
 const [id,,heading,body,target]=tip;
 return `<aside class="tutorial-card" aria-labelledby="tutorial-title" data-tutorial="${id}"><div class="tutorial-copy"><span class="eyebrow">${tr('TUTORIEL SOLO','SOLO TUTORIAL','TUTORIAL INDIVIDUAL')}</span><h2 id="tutorial-title">${tr(...heading)}</h2><p>${tr(...body)}</p></div><div class="tutorial-actions">${btn(tr('Compris','Got it','Entendido'),'tutorial-done',`data-id="${id}"`,'primary')}${target?btn(tr('Voir','Show me','Ver'),'tutorial-target'):''}${btn(tr('Réduire','Minimize','Reducir'),'tutorial-minimize')}${btn(tr('Quitter le tutoriel','Exit tutorial','Salir del tutorial'),'tutorial-stop','','quiet')}</div></aside>`;
}
function tutorialSettings(){if(!S||S.online)return '';const state=tutorialState();return `<div class="tutorial-settings"><strong>${tr('Tutoriel solo','Solo tutorial','Tutorial individual')}</strong><p>${tr('Des conseils pendant votre partie. Votre progression est conservée si vous quittez le tutoriel.','Tips during your game. Progress is kept when you exit the tutorial.','Consejos durante la partida. Tu progreso se conserva al salir del tutorial.')}</p>${btn(state?.enabled?tr('Quitter le tutoriel','Exit tutorial','Salir del tutorial'):tr('Reprendre le tutoriel','Resume tutorial','Retomar tutorial'),state?.enabled?'tutorial-stop':'tutorial-resume')}${state?.enabled&&state.minimized?btn(tr('Afficher les conseils','Show tips','Mostrar consejos'),'tutorial-expand'):''}</div>`;}
function tutorialDecorate(){const tip=tutorialTip();if(!tip||tutorialState()?.minimized)return;const target=tip[4]&&document.querySelector(tip[4]);target?.classList?.add('tutorial-highlight');}

function newForm(){return title(t('new'))+`<div class="setup-grid"><div class="setup-art" style="${parkStyle({logo:selectedLogo})}"></div>${panel(tr('Entrez dans la ligue','Join the league','Entra en la liga'),`<form id="new-form"><label>${t('team_name')}<input name="team" value="${esc(E.logoById(selectedLogo).teamName)}" required maxlength="40" autocomplete="off"></label><label>${t('manager_name')}<input name="manager" value="Manager" required maxlength="40"></label>${logoPicker()}<fieldset><legend>${t('mode')}</legend><label class="choice"><input type="radio" name="mode" value="career" checked><span><strong>${t('career')}</strong><small>${t('career_desc')}</small></span></label><label class="choice"><input type="radio" name="mode" value="free"><span><strong>${t('free_mode')}</strong><small>${t('free_desc')}</small></span></label></fieldset><label class="choice tutorial-option"><input type="checkbox" name="tutorial" value="on"><span><strong>${tr('Activer le tutoriel','Enable tutorial','Activar tutorial')}</strong><small>${tr('Des conseils vous accompagnent pendant le repêchage, la gestion de votre équipe et vos premiers matchs.','Tips guide you through drafting, team management and your first games.','Consejos para el draft, la gestión del equipo y tus primeros partidos.')}</small></span></label><button class="btn primary" type="submit">${t('start')}</button></form>`)}</div>`;}
function savePage(){let saves=savedGames;return title(t('saves'))+`<div class="actions space">${S?btn(t('save'),'save','','primary')+btn(t('export'),'export')+btn(t('quit'),'quit'):''}<label class="btn file-label">${t('import')}<input id="import-file" type="file" accept=".json,application/json"></label>${!S?go(t('back'),'menu'):''}</div><p class="notice">${t('local_note')}</p><div class="save-grid">${saves.length?saves.map(s=>panel(esc(s.name),`<p>${t('season')} ${s.season} · ${s.savedAt?new Date(s.savedAt).toLocaleString(lang):'—'}</p><div class="actions">${btn(t('load'),'load',`data-id="${s.id}"`,'primary',s.corrupt)}${btn(t('backup'),'backup',`data-id="${s.id}"`)}${btn(t('delete'),'delete',`data-id="${s.id}"`,'danger')}</div>`)).join(''):empty(t('empty_saves'))}</div>${panel(t('settings'),`<label class="inline"><input type="checkbox" data-pref="sound" ${prefs.sound?'checked':''}>${t('sound')}</label><label class="inline"><input type="checkbox" data-pref="motion" ${prefs.motion?'checked':''}>${t('motion')}</label>${tutorialSettings()}`)}`;}
function metrics(tid){let a=E.roster(S,E.team(S,tid)).map(p=>p.stats);let sum=k=>a.reduce((n,p)=>n+p[k],0);return {avg:sum('ab')?sum('hits')/sum('ab'):0,hr:sum('hr'),rbi:sum('rbi'),runs:sum('runs'),era:sum('pitchOuts')?sum('earned')*27/sum('pitchOuts'):null,so:sum('pitchSO')};}
function standingTable(src=S){return `<div class="table-scroll"><table><thead><tr><th>#</th><th>${t('team_name')}</th><th>${t('wins')}</th><th>${t('losses')}</th><th>${t('runs')}</th><th>%</th></tr></thead><tbody>${E.standings(src).map((tm,i)=>`<tr class="${tm.id===S.user?'my-team':''}"><td>${i+1}</td><td>${btn(teamMark(tm),'view-team',`data-id="${tm.id}"`,'text-button')}</td><td>${tm.w}</td><td>${tm.l}</td><td>${tm.runs}</td><td>${tm.w+tm.l?n(100*tm.w/(tm.w+tm.l),1):'—'}</td></tr>`).join('')}</tbody></table></div>`;}
function events(items=S.log){return `<ul class="journal">${items.slice(0,20).map(e=>`<li><time>S${e.season} · ${shortDate(e.day??0)}</time><span>${esc(journalText(e))}</span></li>`).join('')}</ul>`;}
function dashboard(){const tm=E.team(S),m=E.userMatch(S),a=metrics(S.user),games=S.schedule.filter(m=>!m.playoff&&m.result&&[m.away,m.home].includes(S.user)),recent=games.slice(-10),incoming=S.trades.filter(t=>t.to===S.user&&t.status==='pending').length;
let career=S.mode==='career'?panel(t('career'),`<div class="manager-data"><strong>${esc(S.manager.name)}</strong><span>${t('level')} <b>${E.level(S)}</b></span><span><b>${S.manager.xp}</b> XP</span><span>${t('reputation')} <b>${S.manager.reputation}/100</b></span><span>${t('points')} <b>${S.manager.points}</b></span><span>${t('season')} <b>${S.season}/10</b></span></div><div class="objectives">${S.manager.objectives.map(o=>`<div class="objective ${o.done?'done':''}"><span>${o.done?'✓':'○'}</span><span>${t('obj_'+o.type)}</span><small>+${o.points} · ${o.xp} XP</small></div>`).join('')}</div>`):'';
let main=S.live?`<h2>${t('match_running')}</h2>${go(t('continue'),'watch','','primary')}`:S.draft?`<span class="eyebrow">${t('spring')} · ${t('week')} 1</span><h2>${t('draft')}</h2><p>${t('draft_required')}</p>${go(t('continue_draft'),'draft','','primary')}`:m?`<span class="eyebrow">${m.playoff?t('playoffs')+' · ':''}${m.result?t('finished'):t('next_match')}</span><div class="matchup"><strong>${teamMark(E.team(S,m.away))}</strong><span class="score">${m.result?m.result.score.join(' : '):'VS'}</span><strong>${teamMark(E.team(S,m.home))}</strong></div><div class="actions center">${m.result?'':btn(t('watch'),'watch-start',`data-id="${m.id}"`,'primary',!!S.careerResult)+btn(t('simulate'),'simulate',`data-id="${m.id}"`,'cream',!!S.careerResult)}</div>`:`<span class="eyebrow">${periods()[Math.floor(S.day/12)]}</span><h2>${S.offseason?t('offseason'):S.playoffs?t('playoffs'):t('rest')}</h2>${S.offseason?go(t('offseason'),'offseason','','primary'):S.playoffs?go(t('playoffs'),'playoffs','','primary'):''}`;
return title(teamMark(tm,'large-team'),badge(`${tm.w} V — ${tm.l} D`))+`${S.careerResult?`<div class="notice result"><h2>${t(S.careerResult)}</h2>${go(tr('Bilan de la dynastie','Dynasty report','Balance de la dinastía'),'dynasty','','primary')}${btn(t('continue_free'),'continue-free')}</div>`:''}<div class="club-overview">${parkView(m?E.team(S,m.home):tm,'dashboard-park')}<div class="hero-game">${main}<div class="actions dashboard-actions">${btn(t('next_day'),'next','','',locked()||!!S.draft||!!S.offseason||!!m&&!m.result)}${btn(t('sim_month'),'month','','',locked()||!!S.draft||!!S.offseason)}${S.lastMatch?go(t('summary'),'match',`data-id="${S.lastMatch}"`):''}${incoming?go(`${t('received')} ${badge(incoming)}`,'trades'):''}</div></div></div>${S.day>=24&&!S.draft?`<div class="notice">${go(tr('Voir les joueurs du prochain repêchage','Scout the next draft','Ver el próximo draft'),'draft')}</div>`:''}${featuredPlayers(tm)}${tradeUpdates()}${S.offseason?`<div class="notice">${go(t('offseason'),'offseason','','primary')}</div>`:''}${career}<div class="stats-grid">${panel(t('offense'),`<div class="metrics"><div><b>${n(a.avg,3)}</b><span>${statIcon('avg')}${t('avg')}</span></div><div><b>${a.hr}</b><span>${statIcon('hr')}${t('hr')}</span></div><div><b>${a.rbi}</b><span>${statIcon('rbi')}RBI</span></div></div>`)}${panel(t('defense'),`<div class="metrics"><div><b>${n(a.era,2)}</b><span>ERA</span></div><div><b>${a.so}</b><span>SO</span></div></div>`)}${panel(t('season_progress'),`<strong class="large">${games.length}<small>/33</small></strong><progress value="${games.length}" max="33"></progress><div class="recent">${recent.map(m=>`<span class="${m.result.winner===S.user?'win':'loss'}">${m.result.winner===S.user?'V':'D'}</span>`).join('')}</div>`)}</div><div class="two-col">${panel(t('standings'),standingTable())}${panel(t('journal'),events())}</div>`;}
function toolbarTabs(options,current,action){return `<div class="tabs" role="tablist">${options.map(k=>`<button role="tab" aria-selected="${k===current}" data-action="${action}" data-tab="${k}" class="${k===current?'selected':''}">${t(k)}</button>`).join('')}</div>`;}
const cols={talent:['contact','power','catch','throw','speed','energy'],offense:['avg','ab','hits','hr','rbi','bb','so'],defense:['balls','catchOuts','throwOuts','errors','def'],pitching:['bf','pitchSO','pitchBB','soPct','era','whip']};
let statSerial=0;
const rawStatIcon=k=>{if(k==='rbi')return '<svg class="stat-icon" viewBox="300 230 640 800" aria-hidden="true" focusable="false"><image href="./assets/rbi-icon.png" width="1254" height="1254"/></svg>';const f=STAT_FRAMES[k],uid='stat-'+(++statSerial);return f?`<svg class="stat-icon" viewBox="${f.join(' ')}" aria-hidden="true" focusable="false"><defs><clipPath id="${uid}"><path d="${STAT_CLIPS[k]}"/></clipPath></defs><image clip-path="url(#${uid})" href="./assets/stat-icons.png" width="1536" height="1024"/></svg>`:'';};
const statIcon=k=>rawStatIcon(k)+helpMark(k);
const colLabel=k=>statIcon(k)+(E.ATTR.includes(k)?({contact:'Con',power:'Pow',catch:'Cat',throw:'Thr',speed:'Spe'})[k]:k==='energy'?t('energy'):t(k));
function sortedPlayers(ids,src=S){let players=ids.map(id=>src.players[id]).filter(Boolean).filter(p=>!favoritesOnly||favoriteIds().includes(p.id)).filter(p=>!filter||p.name.toLocaleLowerCase().includes(filter.toLocaleLowerCase()));let value=(p,k)=>k==='value'?E.tradeValue(p,src):k==='total'?E.total(p):k==='name'?p.name:k==='form'?p.form:k==='grade'?E.GRADES.indexOf(p.grade):E.ATTR.includes(k)?E.eff(p,k):k==='energy'?p.energy:k==='age'?p.age:E.stats(p)[k];players.sort((a,b)=>{let x=value(a,sortKey),y=value(b,sortKey);if(['era','whip'].includes(sortKey)){const missingX=x==null||!Number.isFinite(x),missingY=y==null||!Number.isFinite(y);if(missingX||missingY)return missingX===missingY?0:missingX?1:-1;}return (typeof x==='string'?x.localeCompare(y):(x??-1)-(y??-1))*sortDir;});return players;}
function playerTable(ids,src=S,actions='',showPos=false){const players=sortedPlayers(ids,src);let columns=['name','age','grade','form','value',...cols[route==='draft'?'talent':view]];return `<div class="table-scroll"><table class="players"><thead><tr>${showPos?'<th>Pos</th>':''}${columns.map(k=>`<th aria-sort="${sortKey===k?(sortDir===1?'ascending':'descending'):'none'}">${btn((k==='grade'?t('talent'):k==='form'?t('form'):k==='name'?t('name'):k==='age'?t('age'):rawStatIcon(k)+(E.ATTR.includes(k)?({contact:'Con',power:'Pow',catch:'Cat',throw:'Thr',speed:'Spe'})[k]:t(k)))+(sortKey===k?(sortDir===1?' ↑':' ↓'):''),'sort',`data-key="${k}"`,'sort')}${helpMark(k)}</th>`).join('')}${actions?'<th></th>':''}</tr></thead><tbody>${players.map(p=>{let tm=src.teams.find(tm=>tm.roster.includes(p.id));return `<tr class="${showPos&&params.id?E.position(E.team(src,params.id),p.id)==='Banc'?'bench-row':'':''}">${showPos?`<td>${E.position(tm,p.id)}</td>`:''}<td>${playerLink(p,'',true,tm??null)}${Object.values(p.change||{}).some(v=>v)?`<span class="trend-arrow">${Object.values(p.change).some(v=>v>0)?'↗':'↘'}</span>`:''}</td><td>${p.age}</td><td>${badge(p.grade)}</td><td>${esc(formName(p.form))}</td><td class="number">${n(E.tradeValue(p,src))}</td>${cols[route==='draft'?'talent':view].map(k=>`<td class="number ${k==='energy'&&p.energy<30?'warning':''}">${k==='energy'?`${p.energy}<small>/100</small>`:E.ATTR.includes(k)?E.eff(p,k):statValue(k,E.stats(p)[k])}</td>`).join('')}${actions?`<td>${btn(t(actions),actions,`data-id="${p.id}"`,'small',locked())}</td>`:''}</tr>`;}).join('')||`<tr><td colspan="14">${t('no_results')}</td></tr>`}</tbody></table></div>`;}
function playerTools(){const tabs=route==='draft'?'':toolbarTabs(['talent','offense','defense','pitching'],(teamPreferences||teamRotation)&&route==='team'?'management':view,'view-tab');const favorite=btn('★ '+tr('Favoris','Favorites','Favoritos'),'favorites-filter',`aria-pressed="${favoritesOnly}"`,favoritesOnly?'favorites-active':'');return statsScopeTabs()+`<div class="player-tools">${tabs?tabs.replace('</div>',favorite+(route==='team'&&S.draft?.kind!=='initial'?btn(tr('Rotation des lanceurs','Pitching rotation','Rotación de lanzadores'),'rotation-tab',`role="tab" aria-selected="${teamRotation}"`,'management-tab '+(teamRotation?'selected':''))+btn(tr('Positions préférées','Preferred positions','Posiciones preferidas'),'preferences-tab',`role="tab" aria-selected="${teamPreferences}"`,'management-tab '+(teamPreferences?'selected':'')):'')+'</div>'):favorite}<input aria-label="${t('search')}" id="player-search" type="search" placeholder="${t('search')}" value="${esc(filter)}"></div>`;}
function preferencesTable(src,tm,editable){return `<p>${tr('Deux préférences par joueur. La fatigue reste prioritaire, puis la rotation des lanceurs. Banc en premier réduit le temps de jeu à énergie égale.','Two preferences per player. Fatigue comes first, then pitching rotation. Bench first reduces playing time at equal energy.','Dos preferencias por jugador. Prioridad a la fatiga y rotación. Banquillo primero reduce participación con igual energía.')}</p><div class="table-scroll"><table><thead><tr><th>${t('name')}</th><th>${tr('Premier choix','First choice','Primera opción')}</th><th>${tr('Deuxième choix','Second choice','Segunda opción')}</th></tr></thead><tbody>${tm.roster.map(id=>`<tr><td>${playerLink(src.players[id])}</td>${[0,1].map(i=>`<td><select data-preference-player="${id}" data-preference-index="${i}" aria-label="${esc(src.players[id].name)} · ${i+1}" ${editable?'':'disabled'}>${['',...(i===0?['Bench']:[]),...E.POS].map(pos=>`<option value="${pos}" ${(tm.positionPreferences?.[id]?.[i]||'')===pos?'selected':''}>${pos==='Bench'?tr('Banc','Bench','Banquillo'):pos||tr('Aucune','None','Ninguna')}</option>`).join('')}</select></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function historyDelta(value,previous){const delta=Number.isFinite(previous)?value-previous:0;return `<td class="${delta>0?'stat-rise':delta<0?'stat-fall':''}">${value}${delta?` <small aria-label="${delta>0?'+':''}${delta}">${delta>0?'▲':'▼'} ${Math.abs(delta)}</small>`:''}</td>`;}

const moveAttrs=(id,kind,enabled)=>enabled?`draggable="true" data-move-id="${id}" data-move-kind="${kind}"`:'';
const moveHandle=(p,enabled)=>enabled?`<button type="button" class="move-handle" aria-label="${esc(tr('Déplacer ','Move ','Mover ')+p.name)}" aria-pressed="false">${portrait(p)}</button>`:'';
function lineupSkills(p,defense=false){const st=E.stats(p);return `<span class="lineup-skills">${defense?`<span>${statIcon('catch')}Cat <b>${E.eff(p,'catch')}</b></span><span>${statIcon('throw')}Thr <b>${E.eff(p,'throw')}</b></span><span>${statIcon('speed')}Spe <b>${E.eff(p,'speed')}</b></span>`:`<span>${statIcon('contact')}Con <b>${E.eff(p,'contact')}</b></span><span>${statIcon('power')}Pow <b>${E.eff(p,'power')}</b></span><span>${statIcon('avg')}AVG <b>${n(st.avg,3)}</b></span><span>${statIcon('hr')}HR <b>${st.hr}</b></span>`}</span>`;}
function rotationPanel(src,tm,editable){
 if(archiveId&&!tm.rotation)return '';const r=E.pitchingRotation(src,tm),predicted=E.projectedPitcher(src,tm);
 const explanation=tr('Choisissez de 2 à 4 lanceurs dans l’ordre. À moins de 60 d’énergie, le prochain est ignoré. Si tous sont fatigués, le plus reposé lance. Les autres peuvent jouer à une autre position.','Choose 2–4 pitchers in order. Skip anyone below 60 energy; if all are tired, use the most rested. Other pitchers can play another position.','Elige de 2 a 4 lanzadores en orden. Se omite a quien tenga menos de 60 de energía; si todos están cansados, lanza el más descansado. Los demás pueden jugar en otra posición.');
 return panel(tr('Rotation des lanceurs','Pitching rotation','Rotación de lanzadores'),`<p>${explanation}</p><ol class="pitching-rotation">${r.players.map((id,i)=>{const p=src.players[id];return `<li><span class="rotation-number">${i+1}</span>${playerLink(p,'',true,tm)}<span>${statIcon('throw')} ${p.base.throw}/10 · ${t('energy')} <b class="${p.energy<60?'warning':''}">${p.energy}/100</b></span><span>${id===r.next?badge(tr('Prochain dans l’ordre','Next in order','Siguiente en orden')):editable?btn(tr('Définir comme prochain','Set as next','Marcar siguiente'),'rotation-next',`data-id="${id}"`,'small'):''}${id===predicted?badge(tr('Lanceur prévu · auto','Projected pitcher · auto','Lanzador previsto · auto')):''}</span></li>`;}).join('')}</ol>${editable?`<details class="rotation-editor"><summary>${tr('Modifier les lanceurs et leur ordre','Edit pitchers and order','Editar lanzadores y orden')}</summary><form id="rotation-form"><div class="rotation-selects">${Array.from({length:4},(_,i)=>`<label>${tr('Place','Slot','Puesto')} ${i+1}${i>=2?' · '+tr('facultatif','optional','opcional'):''}<select name="pitcher" ${i<2?'required':''}><option value="">${i<2?tr('Choisir un lanceur','Choose a pitcher','Elegir lanzador'):tr('Aucun','None','Ninguno')}</option>${tm.roster.map(id=>`<option value="${id}" ${r.players[i]===id?'selected':''}>${esc(src.players[id].name)} · THR ${src.players[id].base.throw} · ${t('energy')} ${src.players[id].energy}</option>`).join('')}</select></label>`).join('')}</div><p class="muted">${tr('Un joueur par place. Le prochain tour reste au même joueur s’il fait toujours partie de la rotation; sinon, il revient au premier.','One player per slot. The next turn stays with the same pitcher if retained; otherwise it resets to the first.','Un jugador por puesto. El próximo turno se conserva si el lanzador sigue; si no, vuelve al primero.')}</p><button type="submit" class="btn primary">${tr('Enregistrer la rotation','Save rotation','Guardar rotación')}</button></form></details>`:''}<small>${tr('Le tour avance après le match, à partir du lanceur qui a réellement lancé. En mode manuel, votre lanceur reste inchangé.','The turn advances after the game from the actual pitcher. Manual mode keeps your chosen pitcher.','El turno avanza después del partido desde el lanzador real. En modo manual se conserva tu lanzador.')}</small>`);
}
function teamPage(){let src=dataSource(),tm=E.team(src,params.id||S.user);if(!tm)return empty(t('no_results'));let own=tm.id===S.user&&!archiveId;if(S.draft?.kind==='initial')return title(teamMark(tm,'large-team'),go(t('continue_draft'),'draft','','primary'))+panel(tr('Effectif en cours de repêchage','Roster during draft','Plantilla durante el draft'),playerTools()+playerTable(tm.roster,src));const canMove=own&&!locked();return title(teamMark(tm,'large-team'),go(t('back'),archiveId?'archives':'dashboard'))+(!own&&!archiveId?panel(tr('Recrutement','Recruitment','Reclutamiento'),({contender:tr('Objectif titre : renforcer les postes clés.','Title push: strengthen key positions.','Objetivo título: reforzar posiciones clave.'),rebuild:tr('Reconstruction : privilégier la jeunesse et la couverture des postes.','Rebuilding: prioritize youth and role coverage.','Reconstrucción: priorizar juventud y cobertura.'),balanced:tr('Équilibre : améliorer l’effectif et sa profondeur.','Balanced: improve the roster and its depth.','Equilibrio: mejorar la plantilla y su profundidad.')}[E.npcStrategy(S,tm)])):'')+(archiveId?`<p class="notice">${t('archive_note')} · ${t('season')} ${archiveId}</p>`:'')+`${own?`<div class="actions space">${btn(t('auto_align'),'auto-align','','primary',locked())}${E.userMatch(S)&&!E.userMatch(S).result&&!S.live?go(t('prematch'),'prematch',`data-id="${E.userMatch(S).id}"`):''}<label class="inline switch"><input type="checkbox" id="auto-toggle" ${tm.auto?'checked':''} ${locked()?'disabled':''}>${t('auto')}</label></div>${tm.auto?`<p class="notice">${t('auto_warning')}</p>`:''}`:''}${canMove?`<p class="notice">${tr('Glissez les joueurs pour échanger les postes, modifier l’ordre de frappe ou faire entrer un joueur du banc. Vous pouvez aussi sélectionner deux portraits.','Drag players to swap positions, batting slots or bench players. You can also select two portraits.','Arrastra jugadores para cambiar posiciones, orden o suplentes. También puedes seleccionar dos retratos.')}</p>`:''}<div class="team-visual-layout"><div class="team-field-column">${lineupPark(src,tm,canMove)}${panel(t('bench'),tm.roster.filter(id=>!tm.order.includes(id)).map(id=>`<div class="bench-player" ${moveAttrs(id,'bench',canMove)}>${moveHandle(src.players[id],canMove)}<div class="lineup-player-info">${playerLink(src.players[id],'',!canMove,tm)}${lineupSkills(src.players[id])}${lineupSkills(src.players[id],true)}<small>${statIcon('energy')}${t('energy')} ${src.players[id].energy}/100</small></div></div>`).join('')||'—')}</div><div class="lineup-grid">${panel(t('order'),`<ol class="batting-order">${tm.order.map(id=>`<li ${moveAttrs(id,'offense',canMove)}><div class="batting-player-row">${canMove?moveHandle(src.players[id],true):portrait(src.players[id],'',tm,src)}<div class="lineup-player-info">${playerLink(src.players[id],'',false,tm)}${lineupSkills(src.players[id])}<small class="lineup-energy">${statIcon('energy')}${t('energy')} ${src.players[id].energy}/100</small></div></div></li>`).join('')}</ol>`)}</div></div>${panel(t('team'),playerTools()+(teamRotation?rotationPanel(src,tm,canMove):teamPreferences?preferencesTable(src,tm,canMove):playerTable(tm.roster,src,own?'cut':'',true)))}`; }
function statList(p,keys){let st=E.stats(p);return `<dl class="stat-list">${keys.map(k=>`<div><dt>${statIcon(k)}${t(k)}</dt><dd>${statValue(k,st[k])}</dd></div>`).join('')}</dl>`;}
function profile(){let src=dataSource(),p=src.players[params.id]||S.players[params.id];if(!p)return empty(t('no_results'));let tm=src.teams.find(t=>t.roster.includes(p.id));let own=!archiveId&&S.free.includes(p.id);return title(t('profile'),favoriteButton(p)+btn(t('back'),'profile-back'))+profileNavigation()+statsScopeTabs()+`<div class="profile-grid"><div>${panel(esc(p.name),`<div class="player-card-art" style="${parkStyle(tm)}">${portrait(p,'large-portrait')}${roleArt(tm?.positions.P===p.id?'pitch':'bat',p,tm??null,src)}</div><div class="card-caption">${badge(p.grade)}${helpMark('grade')} ${esc(tm?.name||(S.rookies.includes(p.id)?tr('Disponible au repêchage','Available in the draft','Disponible en el draft'):t(p.retired?'retired_title':'free')))}</div><dl class="stat-list"><div><dt>${t('age')}</dt><dd>${p.age}</dd></div><div><dt>${tr('Forme de carrière','Career form','Forma de carrera')}${helpMark('form')}</dt><dd>${formName(p.form)}</dd></div><div><dt>Side</dt><dd>${esc(p.side)}</dd></div><div><dt>Pos</dt><dd>${tm?E.position(tm,p.id):'—'}</dd></div><div><dt>${statIcon('value')}${t('value')}</dt><dd>${n(E.tradeValue(p,src))}${E.trophyBonus(p,src)>0?`<small class="positive">${tr('dont bonus trophées','including trophy bonus','incluye bonificación por premios')} +${n(E.trophyBonus(p,src),3).replace(/([.,]\d*?)0+$/,'$1').replace(/[.,]$/,'')}</small>`:''}</dd></div></dl>${own?btn(t('sign'),'sign',`data-id="${p.id}"`,'primary',locked()):''}${S.draft&&S.draft.order[S.draft.index]===S.user&&S.rookies.includes(p.id)?btn(t('choose'),'choose',`data-id="${p.id}"`,'primary',locked()):''}`)}</div><div>${panel(tr('Biographie','Biography','Biografía'),`<p>${esc(E.biography(p,lang))}</p>${E.careerStory(p).debut?`<p>${tr("Première arrivée dans la ligue","First league arrival","Primera llegada a la liga")} : S${E.careerStory(p).debut.season} · ${esc(E.careerStory(p).debut.team)}</p>`:""}${E.careerStory(p).clubs.length?`<p>${tr("Clubs de carrière","Career clubs","Clubes de carrera")} : ${E.careerStory(p).clubs.map(esc).join(" · ")}</p>`:""}${E.careerStory(p).titles.length?`<p>★ ${t("champion")} : ${E.careerStory(p).titles.map(n=>"S"+n).join(", ")}</p>`:""}`)}${panel(t('talent'),`${developmentNote(src,p)}<div class="talent-grid"><table><thead><tr><th></th><th>${t('talent')}</th></tr></thead><tbody>${E.ATTR.map(k=>`<tr><th>${statIcon(k)}${k[0].toUpperCase()+k.slice(1)}</th><td><b>${p.base[k]}</b><meter class="attribute-meter" min="0" max="10" value="${p.base[k]}" aria-label="${esc(k)}"></meter>${E.eff(p,k)!==p.base[k]?`<small class="warning">${tr('Avec fatigue','With fatigue','Con fatiga')} : ${E.eff(p,k)}</small>`:''}</td></tr>`).join('')}</tbody></table><div><h3>${t('energy')}</h3><strong class="large">${p.energy}<small>/100</small></strong><progress value="${p.energy}" max="100"></progress><p class="${E.penalty(p)?'warning':''}">${E.penalty(p)?t('fatigue')+' −'+E.penalty(p):t('no_penalty')}</p></div></div>`)}<div class="stats-grid">${panel(t('offense'),statList(p,['avg','ab','runs','hits','singles','doubles','triples','hr','rbi','bb','so']))}${panel(t('defense'),statList(p,['balls','fieldingChances','catchOuts','throwOuts','errors','def']))}${panel(t('pitching'),statList(p,['bf','pitchSO','soPct','pitchBB','allowed','earned','hitsAllowed','pitchOuts','era','whip']))}</div></div></div>${panel(t('journal'),toolbarTabs(['career','progress','stats'],profileTab,'profile-tab')+(profileTab==='career'?`<h3>${statIcon('awards')}${t('awards')}</h3><div class="awards">${p.awards.length?p.awards.map(a=>badge(`${a.rank===1?'★':a.rank} ${t(a.type)} · S${a.season}`,'award')).join(''):t('no_awards')}</div><ul class="journal">${p.journal.map(e=>`<li><time>S${e.season}</time>${esc(journalText({...e,args:{...e.args,name:p.name}}))}</li>`).join('')||t('no_history')}</ul>`:profileTab==='progress'?`<p class="muted">${tr('Attributs au début de chaque saison, après la progression d’intersaison.','Attributes at the start of each season, after offseason development.','Atributos al inicio de cada temporada, después de la progresión.')}</p><div class="table-scroll"><table><thead><tr><th>${t('season')}</th><th>${t('value')}</th>${E.ATTR.map(k=>`<th>${k}</th>`).join('')}</tr></thead><tbody>${(p.attributeHistory||p.history).filter(h=>!archiveId||h.season<=archiveId).sort((a,b)=>a.season-b.season).map((h,i,rows)=>`<tr><td>${h.season}${h.season===src.season&&!archiveId?' · '+tr('en cours','current','actual'):''}</td>${historyDelta(h.value,rows[i-1]?.value)}${E.ATTR.map(k=>historyDelta(h.base[k],rows[i-1]?.base[k])).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="table-scroll"><table><thead><tr><th>${t('season')}</th><th>${t('team_name')}</th><th>${t('value')}</th><th>AVG</th><th>AB</th><th>H</th><th>HR</th><th>RBI</th><th>${t('def')}</th><th>ERA</th><th>${t('soPct')}</th></tr></thead><tbody>${p.history.map(h=>`<tr><td>${h.season}</td><td>${esc(h.team||t('free'))}</td><td>${n(h.value)}</td><td>${n(h.stats.ab?h.stats.hits/h.stats.ab:0,3)}</td><td>${h.stats.ab}</td><td>${h.stats.hits}</td><td>${h.stats.hr}</td><td>${h.stats.rbi}</td>${['def','era','soPct'].map(k=>`<td>${statValue(k,E.stats({stats:h.stats})[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`))}`;}
const calendarTeam=tm=>`<div class="calendar-team">${logoImage(tm.logo)}<span>${esc(tm.name)}</span></div>`;
function calendar(){let src=dataSource(),period=calendarPeriod??Math.floor(S.day/12);return title(t('calendar'))+`<div class="tabs">${periods().map((p,i)=>btn(p,'period',`data-period="${i}"`,i===period?'selected':'')).join('')}</div><div class="calendar-grid">${Array.from({length:12},(_,i)=>{let day=period*12+i,ms=src.schedule.filter(m=>m.day===day);return `<section class="calendar-day ${!archiveId&&day===S.day?'today':''}"><h3>${t('week')} ${Math.floor(i/3)+1} · ${t(['mon','wed','weekend'][i%3])}</h3>${ms.some(m=>[m.home,m.away].includes(S.user))?`<img class="calendar-park" src="./assets/parks/${parkId(E.team(src,ms.find(m=>[m.home,m.away].includes(S.user)).home))}.webp" alt="${esc(parkName(E.team(src,ms.find(m=>[m.home,m.away].includes(S.user)).home)))}" loading="lazy">`:''}${ms.map(m=>`<div class="calendar-match ${[m.home,m.away].includes(S.user)?'user-match':''}">${calendarTeam(E.team(src,m.away))}<b>${m.result?btn(m.result.score.join(' — '),'match-open',`data-id="${m.id}"`,'text-button'):'VS'}</b>${calendarTeam(E.team(src,m.home))}</div>`).join('')||`<p>${period===0&&i<3?t('draft'):t('rest')}</p>`}</section>`;}).join('')}</div>`;}
function leaders(){let src=dataSource(),key=params.key||'avg',leaders=E.leaderboard(src,key);return title(t('leaders'),!archiveId?btn(tr('Vérifier les statistiques','Check statistics','Verificar estadísticas'),'audit'):'')+statsScopeTabs()+`<div class="tabs">${['avg','hr','rbi','def','soPct','era'].map(k=>btn(t(k),'leader-key',`data-key="${k}"`,k===key?'selected':'')).join('')}</div>${panel(t(key),`<p class="muted">${key==='def'?tr('Minimum : 10 occasions défensives (retraits + erreurs). À pourcentage égal : plus d’occasions, puis ordre alphabétique du nom. Le classement utilise le pourcentage exact avant arrondi.','Minimum: 10 fielding chances (outs + errors). Ties: more fielding chances, then player name alphabetically. Ranking uses the exact percentage before rounding.','Mínimo: 10 oportunidades defensivas (outs + errores). Empates: más oportunidades y luego nombre por orden alfabético. Se usa el porcentaje exacto antes de redondear.'):key==='era'?tr('Minimum : 10 manches lancées. La plus petite ERA arrive en premier.','Minimum: 10 innings pitched. Lowest ERA first.','Mínimo: 10 entradas lanzadas. Menor ERA primero.'):t('qualification')}</p><div class="table-scroll"><table><thead><tr><th>#</th><th>${t('name')}</th><th>${t('team_name')}</th><th>${t(key)}</th>${key==='def'?`<th>${t('fieldingChances')}</th><th>${t('errors')}</th>`:''}<th>${t('value')}</th></tr></thead><tbody>${leaders.map((p,i)=>`<tr><td>${i+1}</td><td>${playerLink(p)}</td><td>${esc(p.team)}</td><td><b>${statValue(key,p.metric)}</b></td>${key==='def'?`<td>${n(E.fieldingChances(p))}</td><td>${n(p.stats.errors)}</td>`:''}<td>${n(E.tradeValue(p,src))}</td></tr>`).join('')||`<tr><td colspan="${key==='def'?7:5}">${t('no_results')}</td></tr>`}</tbody></table></div>`)}`;}
function draftPage(){
 const d=S.draft,tm=d?E.team(S,d.order[d.index]):null,initial=d?.kind==='initial',myTurn=tm?.id===S.user;
 const heading=initial?tr('Repêchage de départ','Initial draft','Draft inicial'):t('draft');
 const roundOrder=d?d.order.slice(Math.floor(d.index/6)*6,Math.floor(d.index/6)*6+6):[];
 const board=d?`<p class="muted">${initial?tr('Ordre tiré au hasard, inversé à chaque ronde. 60 joueurs · 8 par équipe · 12 agents libres à la fin.','Random order, reversed each round. 60 players · 8 per team · 12 free agents at the end.','Orden aleatorio, invertido cada ronda. 60 jugadores · 8 por equipo · 12 agentes libres al final.'):tr('Ordre inverse du classement régulier, identique aux deux rondes.','Reverse regular-season standings, same order in both rounds.','Clasificación regular inversa, mismo orden en ambas rondas.')}</p><ol class="draft-order" aria-label="${tr('Ordre de cette ronde','This round’s order','Orden de esta ronda')}">${roundOrder.map((id,i)=>{const team=E.team(S,id);return `<li class="${id===tm.id?'on-clock':''}"><details><summary><span class="draft-rank">${i+1}</span>${teamMark(team)}<strong>${team.roster.length}/8</strong></summary><div class="draft-roster">${team.roster.map(pid=>playerLink(S.players[pid])).join('')||t('no_results')}</div></details></li>`;}).join('')}</ol>`:'';
 return title(heading,go(t('team'),'team'))+(d?`<div class="draft-banner" role="status" aria-live="polite"><span>${t('round')} ${Math.floor(d.index/6)+1}/${d.order.length/6}</span><strong>${teamMark(tm)}</strong><span>${t('pick')} ${d.index+1}/${d.order.length}</span></div>${d.order[d.index+1]?`<div class="draft-next-turn"><b>${tr('Prochain tour','Up next','Próximo turno')}</b>${teamMark(E.team(S,d.order[d.index+1]))}<span>${t('round')} ${Math.floor((d.index+1)/6)+1}</span></div>`:''}${board}<div class="actions space">${myTurn?badge(t('your_turn'))+btn(tr('Choisir pour moi','Choose for me','Elegir por mí'),'draft-auto-one','','',locked())+(!initial?btn(tr('Passer mon tour','Skip my turn','Pasar mi turno'),'draft-skip','','',locked()):''):btn(tr('Sélection NPC suivante','Next NPC selection','Siguiente elección NPC'),'draft-next','','primary',locked())+btn(tr('Aller à mon prochain choix','Go to my next pick','Ir a mi siguiente elección'),'draft-until-user','','',locked())}${btn(tr('Simuler le reste du repêchage','Simulate the remaining draft','Simular el resto del draft'),'draft-auto','','',locked())}</div>`:`<p class="notice">${S.rookies.length?t('rookies'):t('draft_done')}</p>`)
 +panel(initial?tr('Joueurs disponibles','Available players','Jugadores disponibles'):t('rookies'),S.rookies.length?playerTools()+playerTable(S.rookies,S,myTurn?'choose':''):empty(t('no_rookies')))
 +panel(t('pick'),`<ul class="journal draft-journal">${(d?.picks||S.lastDraft||[]).slice().reverse().map(p=>`<li><time>${t('round')} ${p.round}${p.pick?' · #'+p.pick:''}</time><span>${esc(p.team)}</span>${p.skipped?`<span class="muted">${tr('Tour passé','Pick skipped','Turno pasado')}</span>`:playerLink(S.players[p.id])}</li>`).join('')}</ul>`);
}
function archivePage(){return title(t('archives'),go(tr('Bilan de la dynastie','Dynasty report','Balance de la dinastía'),'dynasty'))+`${archiveId?`<p class="notice">${t('archive_note')} · ${t('season')} ${archiveId} ${btn(t('close'),'archive-close')}</p><div class="actions space">${go(t('calendar'),'calendar')}${go(t('leaders'),'leaders')}${go(t('playoffs'),'playoffs')}</div>${standingTable(dataSource())}${awardCards(dataSource())}${panel(t('league'),events(dataSource().leagueNews||[]))}`:`<div class="save-grid">${S.archives.length?S.archives.slice().reverse().map(a=>panel(`${t('season')} ${a.season}`,`<h3>★ ${esc(E.team(a,a.winner).name)}</h3>${btn(t('load'),'archive-open',`data-season="${a.season}"`,'primary')}`)).join(''):empty(t('no_archives'))}</div>`}${panel(tr('Records de saison · saisons terminées','Season records · completed seasons','Récords de temporada · temporadas terminadas'),E.leagueRecords(S).map(r=>`<p><strong>${t(r.key)} : ${r.value}</strong> — ${esc(r.name)} · S${r.season}</p>`).join('')||t('no_history'))}${panel(t('retired_title'),S.retired.length?S.retired.map(id=>`<div class="bench-player">${playerLink(S.players[id],'',true,null)}<span>${S.players[id].age}</span></div>`).join(''):empty(t('no_results')))}`;}
function seasonPage(developmentOnly=false){let r=S.summary;if(!r)return empty(t('no_archives'));const selected=params.developmentTeam==='all'||S.teams.some(tm=>tm.id===params.developmentTeam)?params.developmentTeam:S.user,owners=new Map(S.teams.flatMap(tm=>tm.roster.map(id=>[id,tm]))),changes=r.changes.filter(c=>owners.has(c.id)&&!r.retirements.includes(c.id)&&(selected==='all'||owners.get(c.id).id===selected));return (developmentOnly?'':title(`${t('season_report')} ${r.season}`))+`${developmentOnly?'':`<div class="champion-banner"><span>★</span><div><small>${t('champion')}</small><h2>${esc(r.winner)}</h2></div></div>${awardCards(S.archives.find(a=>a.season===r.season))}`}${panel(t('progress'),`<label>${tr('Équipe à consulter','View team','Ver equipo')}<select id="development-team">${S.teams.map(tm=>`<option value="${tm.id}" ${selected===tm.id?'selected':''}>${esc(tm.name)}</option>`).join('')}<option value="all" ${selected==='all'?'selected':''}>${tr('Toutes les équipes','All teams','Todos los equipos')}</option></select></label><div class="table-scroll"><table><thead><tr><th>${t('name')}</th><th>${t('team_name')}</th><th>${t('value')}</th>${E.ATTR.map(k=>`<th>${k}</th>`).join('')}</tr></thead><tbody>${changes.map(c=>`<tr><td>${playerLink(S.players[c.id])}</td><td>${esc(owners.get(c.id).name)}</td><td>${n(E.tradeValue(S.players[c.id],S))}</td>${E.ATTR.map(k=>`<td class="${c.delta[k]>0?'positive':c.delta[k]<0?'warning':''}">${c.delta[k]>0?'+':''}${c.delta[k]||'—'}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="8">${t('no_results')}</td></tr>`}</tbody></table></div>`)}${panel(t('retirements'),r.retirements.length?r.retirements.map(id=>`<p>${playerLink(S.players[id],'',true,null)}</p>`).join(''):empty(t('no_results')))}`;}

function tradeHelp(){return panel(tr('Comment l’équipe décide','How the team decides','Cómo decide el equipo'),`<p>${tr('Réponse après 2 jours de jeu. Le club compare la valeur des joueurs et les points, puis l’effet sur son alignement, ses besoins et sa stratégie. Une part aléatoire intervient : une valeur égale ne garantit pas une acceptation.','Reply after 2 game days. The club compares player values and points, then lineup impact, needs and strategy. A random factor applies: equal value does not guarantee acceptance.','Respuesta tras 2 días de juego. El club compara valores y puntos, el impacto en su alineación, necesidades y estrategia. Hay azar: un valor igual no garantiza la aceptación.')}</p><p>${tr('La réponse et son motif restent dans Envoyées, même après un refus. Une acceptation nécessite ta confirmation finale. Les offres expirent après 7 jours.','The reply and reason remain in Sent, including rejections. Accepted offers require your final confirmation. Offers expire after 7 days.','La respuesta y el motivo quedan en Enviadas, incluso los rechazos. Debes confirmar las ofertas aceptadas. Caducan después de 7 días.')}</p>`);}
function tradeFeedback(x){const d=x.decision;const reasons={lineup:tr('Le club juge que cet échange affaiblirait trop son effectif.','The club believes this trade would weaken its roster too much.','El club considera que debilitaría demasiado su plantilla.'),value:tr('La valeur et les bénéfices proposés sont insuffisants pour convaincre le club.','The offered value and benefits were insufficient to convince the club.','El valor y los beneficios no convencen al club.'),accepted:tr('Le club estime que la valeur et l’effet sur son effectif sont acceptables. Confirme pour conclure.','The club considers the value and roster impact acceptable. Confirm to complete.','El club considera aceptables el valor y el impacto. Confirma para completar.'),countered:tr('Le club propose de rééquilibrer les points. Consulte les offres reçues.','The club proposes adjusting the points. See Received offers.','El club propone ajustar los puntos. Consulta Recibidas.')};return x.status==='pending'?(x.from===S.user?tr(`Réponse dans ${Math.max(0,2-(E.absolute(S)-x.created))} jour(s) de jeu.`,`Reply in ${Math.max(0,2-(E.absolute(S)-x.created))} game day(s).`,`Respuesta en ${Math.max(0,2-(E.absolute(S)-x.created))} día(s).`):t('pending')):`<p>${d?reasons[d.reason]||t(x.status):t(x.status)}</p>${d?`<small>${tr('Valeur offerte / demandée','Offered / requested value','Valor ofrecido / solicitado')} : ${d.offer} / ${d.ask} · ${tr('Impact effectif','Roster impact','Impacto en plantilla')} : ${n(d.gain,1)}</small>`:''}`;}
function tradeUpdates(){const replies=[...S.trades,...S.tradeHistory].filter(x=>x.from===S.user&&['accepted','rejected','countered','expired','stale'].includes(x.status)).sort((a,b)=>(b.decision?.day??b.created)-(a.decision?.day??a.created)).slice(0,3);return replies.length?panel(tr('Réponses aux échanges','Trade replies','Respuestas a intercambios'),replies.map(x=>`<p><b>${esc(E.team(S,x.to).name)} · ${t(x.status)}</b></p>${tradeFeedback(x)}`).join('')+go(t('trades'),'trades')):'';}

function tradeCard(x,history=false){const incoming=x.to===S.user,other=E.team(S,incoming?x.from:x.to),names=(ids,owner)=>ids.map(id=>playerLink(S.players[id],'',true,owner)).join('');return panel(`${esc(other.name)} ${badge(t(x.status))}${x.counter?' · '+t('counter'):''}`,`<div class="trade-feedback">${tradeFeedback(x)}</div><div class="trade-pair"><div><h3>${t('offered')}</h3><small>${esc(E.team(S,x.from).name)}</small>${names(x.offered,E.team(S,x.from))}<p>${t('points')} : ${x.pay}</p></div><div><h3>${t('asked')}</h3><small>${esc(E.team(S,x.to).name)}</small>${names(x.asked,E.team(S,x.to))}<p>${t('points')} : ${x.receive}</p></div></div>${!history?`<div class="actions">${incoming||x.status==='accepted'?btn(t('accept'),'trade-accept',`data-id="${x.id}"`,'primary',locked()):''}${btn(t('refuse'),'trade-refuse',`data-id="${x.id}"`,'',locked())}</div>`:''}`);}
function trades(){let list=tradeTab==='trade_history'?S.tradeHistory:tradeTab==='received'?S.trades.filter(x=>x.to===S.user):[...S.trades,...S.tradeHistory].filter(x=>x.from===S.user);return title(t('trades'),go(t('new_trade'),'trade-new','','primary'))+`<p class="notice">${t('trade_delay')} · ${t('points')} : ${S.manager.points}</p>${toolbarTabs(['received','sent','trade_history'],tradeTab,'trade-tab')}<div class="two-col">${list.map(x=>tradeCard(x,tradeTab==='trade_history'||!S.trades.some(t=>t.id===x.id))).join('')||empty(t('no_trades'))}</div>${btn(t('request_offer'),'offer-request','','',locked())}`;}
function tradeForm(){let other=E.team(S,params.to||'t1');let choices=(tm,name)=>tm.roster.map(id=>{let p=S.players[id];return `<label class="trade-choice"><input type="checkbox" name="${name}" value="${id}">${portrait(p)}<span>${esc(p.name)}<small>${p.age} · ${E.total(p)} / 50 · ${t('value')} ${n(E.tradeValue(p,S))}</small></span></label>`;}).join('');return title(t('new_trade'),go(t('back'),'trades'))+tradeHelp()+`<form id="trade-form"><label>${t('team_name')}<select name="to" id="trade-team">${S.teams.filter(tm=>tm.id!==S.user).map(tm=>`<option value="${tm.id}" ${tm.id===other.id?'selected':''}>${esc(tm.name)}</option>`).join('')}</select></label><div class="two-col">${panel(t('offered'),choices(E.team(S),'offered')+`<label>${t('pay')}<input name="pay" type="number" min="0" max="${S.manager.points}" step="1" value="0" required></label>`)}${panel(t('asked'),choices(other,'asked')+`<label>${t('receive')}<input name="receive" type="number" min="0" step="1" value="0" required></label>`)}</div><p class="notice">${t('trade_roster')} · ${t('points')} ${S.manager.points}</p><button class="btn primary" ${locked()?'disabled':''}>${t('send')}</button></form>`;}
function matchData(){return S.live||dataSource().schedule.find(m=>m.id===params.id)?.result;}
function boxscore(m){return `<div class="table-scroll scoreboard"><table><thead><tr><th>${t('team_name')}</th>${Array.from({length:Math.max(6,m.box[0].length,m.box[1].length)},(_,i)=>`<th>${i+1}</th>`).join('')}<th>R</th>${m.gameStats?'<th>H</th><th>E</th>':''}</tr></thead><tbody>${[m.away,m.home].map((id,j)=>`<tr><th>${teamMark(E.team(dataSource(),id))}</th>${Array.from({length:Math.max(6,m.box[0].length,m.box[1].length)},(_,i)=>`<td>${m.box[j][i]??'–'}</td>`).join('')}<td><b>${m.score[j]}</b></td>${m.gameStats?['hits','errors'].map(k=>`<td>${m.gameStats.find(tm=>tm.id===id).players.reduce((sum,p)=>sum+p.stats[k],0)}</td>`).join(''):''}</tr>`).join('')}</tbody></table></div>`;}
function playRow(e){return `<li class="play-event ${e.runs?'scoring':''}"><time>${e.half?'▼':'▲'} ${e.inning}</time><div><b>${esc(e.batter)}</b> · ${t(e.type)}${e.where?' → '+e.where:''}${e.runs?` <strong>+${e.runs}</strong>`:''}<small>${esc(e.defender||'')} · ${e.outs} ${t('outs')} · ${e.score.join(' : ')}</small>${e.checks?.length?`<details><summary>${tr('Calculs de l’action','Play calculations','Cálculos de la jugada')}</summary>${e.checks.map(([k,a,b])=>`<span>${t(k)} : ${a} / (${a} + ${b})</span>`).join('<br>')}</details>`:''}</div></li>`;}
function fieldActors(src,m,def,off,batter,bases,e,activeScene){
 const a=parkLandmarks[parkId(E.team(src,m.home))];
 const points=[[50,a[7]],[a[0],a[1]],[a[2],a[3]],[a[4],a[5]],[50,a[7]]];
 const slots={P:[50,a[6]],C:[50,Math.min(97,a[7]+6)],GO:[32,a[5]-4],GE:[68,a[1]-4],FO:[33,42],FE:[67,42]};
 const duration=activeScene?.duration||0,elapsed=activeScene?Date.now()-activeScene.startedAt:0;
 const moves=activeScene?runnerTransitions(activeScene.previous,e):[];
 const actor=(p,tm,pose,x,y,cls,extra='')=>p?`<button type="button" class="field-actor ${cls}" data-action="profile" data-id="${esc(p.id)}" aria-label="${esc(p.name)}" title="${esc(p.name)}" style="left:${x}%;top:${y}%;${extra}">${roleArt(pose,p,tm,src)}<span class="actor-name">${esc(p.name)}</span></button>`:'';
 let html=E.POS.map(pos=>{const [x,y]=slots[pos],p=src.players[def.positions[pos]],active=!!activeScene&&(e.where===pos||pos==='P');return `<span class="defender-marker" data-position="${pos}">${actor(p,def,pos==='P'?'pitch':active&&e.type==='T'?'throw':'catch',x,y,'defender '+(active?'fielder-active':''))}</span>`;}).join('');
 const batterMoving=moves.some(r=>r.id===batter?.id);
 if(!batterMoving)html+=actor(batter,off,activeScene&&!['BB','K'].includes(e.type)?'swing':'bat',44,a[7],'batter-actor');
 bases.forEach((r,i)=>{if(r&&!moves.some(m=>m.id===r.id))html+=actor(src.players[r.id],off,'run',points[i+1][0],points[i+1][1],'runner runner-stationary');});
 moves.forEach((r,i)=>{
  const path=points.slice(r.from,r.to+1),[x,y]=path.at(-1);
  const frames=path.map(([px,py],j)=>`${j/(path.length-1)*96}%{left:${px}%;top:${py}%;opacity:1}`).join('')+`100%{left:${x}%;top:${y}%;opacity:${r.scored?0:1}}`;
  html+=`<style>@keyframes runner-path-${i}{${frames}}</style>`+actor(src.players[r.id],off,'run',x,y,'runner runner-moving'+(r.scored?' runner-scored':''),`animation:runner-path-${i} ${duration}ms linear -${elapsed}ms both;`);
 });
 if(activeScene&&e?.where&&slots[e.where]){const target=slots[e.where],[hx,hy]=points[0];html+=`<style>@keyframes play-ball{0%{left:50%;top:${a[6]}%;opacity:1}28%{left:${hx}%;top:${hy}%;opacity:1}90%{left:${target[0]}%;top:${target[1]}%;opacity:1}100%{left:${target[0]}%;top:${target[1]}%;opacity:0}}</style><span class="play-ball" aria-hidden="true" style="animation:play-ball ${duration}ms linear -${elapsed}ms both"></span>`;}
 return html;
}
function watch(){
 const m=matchData();if(!m)return empty(t('match_unavailable'));
 const live=!!S.live,ev=m.events||[],activeScene=scene?.matchId===m.id?scene:null;
 const e=activeScene?.event||(!live&&replayIndex>0?ev[replayIndex-1]:null);
 const score=e?.score||(live?m.score:[0,0]),bases=e?.bases||(live?m.bases:[null,null,null]);
 const half=e?.half??(live?m.half:0),inning=e?.inning??(live?m.inning:1),src=dataSource();
 const offense=E.team(src,half?m.home:m.away),defense=E.team(src,half?m.away:m.home);
 const off={...offense,...replayLineup(m,offense)},def={...defense,...replayLineup(m,defense)};
 const batter=src.players[e?.batterId||(live?off.order[m.indices[half]]:off.order[0])],pitcher=src.players[e?.pitcherId||def.positions.P]
;return title(live?t('watch'):t('replay'),go(t('back'),'dashboard'))+`<div class="match-board"><div><small>${t('away')}</small><h2>${teamMark(E.team(src,m.away),'large-team')}</h2></div><strong class="score">${score.join(' : ')}</strong><div><small>${t('home')}</small><h2>${teamMark(E.team(src,m.home),'large-team')}</h2></div></div>${live?boxscore(m):''}<div class="live-grid"><div class="field-wrap"><div style="${parkStyle(E.team(src,m.home))}" class="field ${activeScene?'scene-playing play-pulse play-'+esc(e.type):''}" aria-label="${t('bases')}"><div class="field-home-label">${esc(parkName(E.team(src,m.home)))}</div>${[0,1,2].map((b)=>`<div class="base base-${b} ${bases[b]?'occupied':''}"><span>${b+1}</span>${bases[b]?`<small>${esc(src.players[bases[b].id]?.name||'')}</small>`:''}</div>`).join('')}<div class="home-plate"></div>${fieldActors(src,m,def,off,batter,bases,e,activeScene)}<div class="field-caption">${inning} · ${t(half?'lower':'upper')} <span>${e?.outs??(live?m.outs:0)} / 3 ${t('outs')}</span></div>${momentBanner(m)}${e?`<div class="action-call ${e.runs?'run-call':''}" key="${ev.length}">${t(e.type)}${e.runs?' +'+e.runs:''}</div>`:''}</div><div class="actions space">${btn(t(replayTimer?'pause':'play'),'play-toggle','','primary',!live&&replayIndex>=ev.length)}${btn(t('step'),'play-step','','',!live&&replayIndex>=ev.length)}${live?btn(t('finish'),'play-finish'):btn(t('replay'),'replay-reset')}<select id="play-speed" aria-label="${t('play')}"><option value="1200" ${playSpeed===1200?'selected':''}>1×</option><option value="600" ${playSpeed===600?'selected':''}>2×</option><option value="250" ${playSpeed===250?'selected':''}>4×</option></select></div>${!live?`<progress value="${replayIndex}" max="${ev.length||1}"></progress>`:''}</div><div>${panel(t('batter'),`<div class="duel-art" style="${parkStyle(E.team(src,m.home))}">${roleArt('bat',batter,off,src)}</div><div class="match-player">${portrait(batter,'medium-portrait',off,src)}<div><strong class="team-identity">${teamMark(off)} · ${t(half?'home':'away')}</strong>${playerLink(batter,'',true,off)}<small>${colLabel('contact')} ${E.eff(batter,'contact')} · ${colLabel('power')} ${E.eff(batter,'power')} · ${t('energy')} ${batter.energy}</small></div></div>`)}${panel(t('pitcher'),`<div class="duel-art pitcher-duel" style="${parkStyle(E.team(src,m.home))}">${roleArt('pitch',pitcher,def,src)}</div><div class="match-player">${portrait(pitcher,'medium-portrait',def,src)}<div><strong class="team-identity">${teamMark(def)} · ${t(half?'away':'home')}</strong>${playerLink(pitcher,'',true,def)}<small>Thr ${E.eff(pitcher,'throw')} · ${t('energy')} ${pitcher.energy}</small></div></div>`)}${panel(t('details'),`<ol class="play-list latest">${(live?ev:ev.slice(0,replayIndex)).slice(-5).reverse().map(playRow).join('')||t('step')}</ol>`)}</div></div>`;}
function gameSummary(m){
 const src=dataSource(),winner=E.team(src,m.winner),innings=Math.max(m.box[0].length,m.box[1].length);
 const recap=`<p class="match-recap"><strong>${esc(winner.name)}</strong> ${tr('remporte le match','wins','gana')} ${Math.max(...m.score)}–${Math.min(...m.score)} · ${innings} ${tr('manches','innings','entradas')}.</p>`;
 if(!m.gameStats)return recap+`<p class="notice">${tr('Les statistiques individuelles ne sont pas disponibles pour ce match joué avant cette mise à jour.','Individual statistics are unavailable for this game played before this update.','No hay estadísticas individuales para este partido anterior a la actualización.')}</p>`;
 const table=(players,columns)=>`<div class="table-scroll"><table><thead><tr><th>${t('name')}</th><th>Pos</th><th>${t('value')}</th>${columns.map(([label,k])=>`<th>${label}${helpMark(k)}</th>`).join('')}</tr></thead><tbody>${players.map(p=>`<tr><th>${playerLink(S.players[p.id]||p,'',false)}</th><td>${p.pos}</td><td>${n(p.value)}</td>${columns.map(([,k])=>`<td>${k==='ip'?Math.floor(p.stats.pitchOuts/3)+'.'+p.stats.pitchOuts%3:p.stats[k]}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 return recap+m.gameStats.map(tm=>panel(esc(E.team(src,tm.id).name),`<h3>${t('offense')}</h3>${table(tm.players,[['AB','ab'],['R','runs'],['H','hits'],['2B','doubles'],['3B','triples'],['HR','hr'],['RBI','rbi'],['BB','bb'],['SO','so']])}<h3>${t('pitching')}</h3>${table(tm.players.filter(p=>p.stats.bf),[['IP','ip'],['BF','bf'],['H','hitsAllowed'],['R','allowed'],['ER','earned'],['BB','pitchBB'],['SO','pitchSO']])}`)).join('')+`<p class="muted">${tr('AB : présences officielles · R : points · H : coups sûrs · 2B / 3B : doubles / triples · HR : circuits · RBI : points produits · BB : buts sur balles · SO : retraits au bâton · IP : manches lancées (.1 / .2 = 1 / 2 retraits) · BF : frappeurs affrontés · ER : points mérités · E : erreurs.','AB: at bats · R: runs · H: hits · 2B / 3B: doubles / triples · HR: home runs · RBI: runs batted in · BB: walks · SO: strikeouts · IP: innings pitched (.1 / .2 = 1 / 2 outs) · BF: batters faced · ER: earned runs · E: errors.','AB: turnos · R: carreras · H: hits · 2B / 3B: dobles / triples · HR: jonrones · RBI: carreras impulsadas · BB: bases por bolas · SO: ponches · IP: entradas (.1 / .2 = 1 / 2 outs) · BF: bateadores · ER: carreras limpias · E: errores.')}</p>`;
}
function matchSummary(){let m=dataSource().schedule.find(m=>m.id===params.id)?.result;if(!m)return empty(t('match_unavailable'));return title(t('summary'),go(t('dashboard'),'dashboard')+(m.events?.length?btn(t('replay'),'replay-start',`data-id="${m.id}"`,'primary'):''))+`<div class="match-board"><h2>${teamMark(E.team(dataSource(),m.away),'large-team')}</h2><strong class="score">${m.score.join(' : ')}</strong><h2>${teamMark(E.team(dataSource(),m.home),'large-team')}</h2></div>${boxscore(m)}${gameSummary(m)}${panel(t('highlights'),`<ol class="play-list">${(m.events||m.highlights||[]).filter(e=>e.runs).map(playRow).join('')||t('no_highlights')}</ol>`)}${m.events?.length?panel(t('details'),`<details><summary>${m.events.length} ${tr('actions — afficher le déroulé complet','plays — show full play-by-play','jugadas — ver todas')}</summary><ol class="play-list">${m.events.map(playRow).join('')}</ol></details>`):`<p class="notice">${tr('Le dernier match joué reste disponible en rediffusion. Les autres matchs conservent leur bilan et jusqu’à cinq faits saillants.','Your most recent game remains available for replay. Other games retain their summary and up to five highlights.','Puedes repetir tu último partido. Los otros partidos conservan su resumen y hasta cinco jugadas destacadas.')}</p>`}`;}
function rules(){const sections=[
[tr('00 / L’année sportive','00 / The season','00 / El año deportivo'),tr('Le printemps commence par le repêchage. Les 33 matchs de saison régulière se terminent en automne. En hiver, les quatre premiers jouent les demi-finales (1 contre 4, 2 contre 3), au meilleur de trois, puis la finale au meilleur de cinq. Le mieux classé reçoit les matchs impairs. Les statistiques des séries sont séparées. Le titre et l’objectif de carrière reviennent au vainqueur de la finale. L’intersaison déroule les récompenses, la progression et les retraites, puis la confirmation de fin de saison ouvre directement le repêchage suivant. L’alignement automatique choisit le lanceur selon la rotation et la fatigue, puis cinq autres joueurs selon leur énergie et leurs talents.','Spring starts with the draft. The 33 regular games end in autumn. The top four play winter best-of-three semifinals (1–4, 2–3), then a best-of-five final. The higher seed hosts odd games. Playoff stats are separate. The final winner earns the title and career objective. Offseason has two steps: awards, then development and retirement; confirmation opens the next draft. Auto lineup uses the pitching rotation and fatigue, then selects five others by energy and skills.','La primavera comienza con el draft. Los 33 partidos regulares terminan en otoño. Los cuatro primeros disputan semifinales invernales al mejor de tres (1–4, 2–3) y la final al mejor de cinco. El mejor clasificado recibe los partidos impares. Las estadísticas de eliminatorias son separadas. El ganador de la final logra el título. La entretemporada tiene dos pasos: premios y desarrollo/retiros; al confirmar se abre el siguiente draft. La alineación automática usa la rotación y fatiga para el lanzador y elige cinco más según energía y talento.')],
[tr('01 / Prendre les commandes','01 / Take charge','01 / Toma el mando'),tr('Commencez avec six équipes vides : choisissez parmi 60 joueurs de 21 à 30 ans pendant huit rondes. L’ordre est tiré au hasard puis inversé à chaque ronde. Chaque équipe obtient huit joueurs; les douze autres deviennent agents libres. Les saisons suivantes ont un repêchage annuel de deux tours. Dans Gestion équipe, ajustez la défense et l’ordre de frappe. Jouez ensuite le match du jour, puis avancez le calendrier.','Start with six empty teams: select from 60 players aged 21–30 over eight rounds. A random order reverses each round. Each team gets eight players; the remaining twelve become free agents. Later seasons have a two-round annual draft. Set fielding positions and batting order in Team management. Play today’s game, then advance the calendar.','Empieza con seis equipos vacíos: elige entre 60 jugadores de 21–30 años durante ocho rondas. El orden aleatorio se invierte cada ronda. Cada equipo recibe ocho jugadores; los doce restantes son agentes libres. Las siguientes temporadas tienen un draft anual de dos rondas. Ajusta la defensa y el orden de bateo. Juega el partido del día y avanza el calendario.')],
[tr('02 / Calendrier et repos','02 / Calendar and rest','02 / Calendario y descanso'),tr('Une année comporte 48 journées de jeu et 33 matchs réguliers par équipe. Le classement se décide par victoires, points marqués puis nom d’équipe. Le champion est le vainqueur de la finale. Après le dernier match régulier, une journée entière de repos précède les demi-finales. Les matchs de demi-finale sont consécutifs. La finale commence après une journée entière de repos suivant la dernière demi-finale. Les matchs 1 à 4 sont consécutifs; si nécessaire, une journée de repos sépare les matchs 4 et 5. Un jour sans match restaure l’énergie à 100. Les séries déjà commencées avant cette mise à jour gardent leur calendrier.','48 game days and 33 regular games per team. Standings use wins, runs, then team name; the final winner is champion. One full rest day precedes the semifinals. Semifinal games are consecutive. The final starts after a full rest day following the last semifinal. Games 1–4 are consecutive, with a rest day before game 5 if needed. Rest restores energy to 100. Already-started older playoffs retain their schedule.','48 jornadas y 33 partidos regulares por equipo. Clasificación por victorias, carreras y nombre. El ganador de la final es campeón. Descanso antes de semifinales y final. Partidos consecutivos, excepto un descanso entre partidos 4 y 5 de la final. El descanso restaura energía a 100. Eliminatorias antiguas iniciadas conservan su calendario.')],
[tr('03 / Six joueurs sur le terrain','03 / Six on the field','03 / Seis en el campo'),tr('L’effectif compte de six à huit joueurs. P : lanceur, C : receveur, GO / GE : défense intérieure côté impair / pair, FO / FE : champ extérieur côté impair / pair. Les six titulaires frappent dans l’ordre choisi, qui continue d’une manche à l’autre. Une permutation avec le banc remplace le joueur à la fois au bâton et en défense. L’alignement auto privilégie l’énergie et les attributs utiles aux postes. Désactivez-le pour conserver vos choix.','Keep six to eight players. P: pitcher, C: catcher, GO / GE: odd / even infield, FO / FE: odd / even outfield. Six starters bat in your chosen order, continuing across innings. Bench swaps replace fielding and batting slots together. Auto lineup prioritizes energy and position skills. Turn it off to preserve your choices.','Mantén entre seis y ocho jugadores. P: lanzador, C: receptor, GO / GE: cuadro impar / par, FO / FE: exterior impar / par. Los seis titulares batean en orden continuo. Los cambios con el banquillo afectan defensa y bateo. La alineación automática prioriza energía y habilidades. Desactívala para conservar tus elecciones.')],
[tr('04 / Le match','04 / The game','04 / El partido'),tr('Six manches, trois retraits par demi-manche. L’équipe visiteuse frappe en premier. En cas d’égalité, des manches supplémentaires continuent jusqu’à un vainqueur. Le match peut se terminer dès que l’équipe à domicile prend l’avance en fin de sixième manche ou après. Les actions distinguent retraits au bâton, buts sur balles, attrapés, relais, erreurs et coups sûrs. Sur un but sur balles, seuls les coureurs forcés avancent. Une meilleure capacité de lancer réduit le risque de but sur balles; la fatigue augmente ce risque.','Six innings, three outs per half. The away team bats first. Ties continue into extra innings until a winner emerges. The home team wins immediately upon taking the lead in the bottom of the sixth or later. Plays include strikeouts, walks, catches, throws, errors and hits. Walks only advance forced runners. Better throwing skill reduces walk risk; fatigue increases it.','Seis entradas, tres eliminados por mitad. El visitante batea primero. Los empates continúan con entradas extra. El local gana al tomar ventaja en la parte baja de la sexta o después. Hay ponches, bases por bolas, atrapadas, tiros, errores y hits. En una base por bolas solo avanzan los corredores forzados. Una mayor habilidad de lanzamiento reduce ese riesgo; la fatiga lo aumenta.')],
[tr('05 / Talent et fatigue','05 / Skills and fatigue','05 / Talento y fatiga'),tr('Contact, Power, Catch, Throw et Speed vont de 1 à 10. La classe initiale A+ à D décrit le talent de départ, pas une note recalculée chaque année. Chaque action dépense de l’énergie chez le frappeur, le lanceur et le défenseur sollicité. Sous 30 : −1 à tous les attributs ; sous 10 : −2. Les attributs restent au minimum à 1. Le banc récupère à 100 après un match, tous les joueurs durant les jours de repos.','Contact, Power, Catch, Throw and Speed range from 1 to 10. A+ to D is the starting talent class, not an annually recalculated grade. Batters, pitchers and involved fielders spend energy each play. Below 30: −1 to every skill; below 10: −2, with a minimum of 1. Bench players recover to 100 after games; everyone recovers on rest days.','Contact, Power, Catch, Throw y Speed van de 1 a 10. A+ a D indica el talento inicial. Bateadores, lanzadores y defensores implicados gastan energía. Bajo 30: −1 en todo; bajo 10: −2, mínimo 1. El banquillo recupera 100 tras el partido; todos en días de descanso.')],
[tr('06 / Progression et recrutement','06 / Development and recruitment','06 / Progresión y fichajes'),tr("Les joueurs vieillissent à leur anniversaire. À l’intersaison, chaque attribut fait un seul tirage selon l’âge et la forme de carrière : développement, sommet ou déclin. Le résultat peut être nul. Les retraites gardent leurs règles d’âge et de talent. Dès l’automne, 24 recrues sont consultables. Le repêchage annuel suit l’ordre inverse du classement à chaque tour; les non-choisis deviennent agents libres.","Players age on their birthday. Each offseason, every skill receives one age- and career-based roll: growth, peak or decline. No change is possible. Retirement retains its age and talent rules. Scout 24 rookies from autumn. Every annual draft round follows reverse standings; undrafted rookies become free agents.","Los jugadores envejecen en su cumpleaños. En cada entretemporada, cada atributo tiene un sorteo según edad y carrera: desarrollo, apogeo o declive. Puede no cambiar. Las retiradas conservan sus reglas de edad y talento. Desde otoño se observan 24 novatos; cada ronda anual sigue el orden inverso de clasificación y los no elegidos quedan libres.")],
[tr('07 / Échanges et carrière','07 / Trades and career','07 / Intercambios y carrera'),tr('Proposez plusieurs joueurs et des points de manager. L’IA répond après deux jours : accord, refus ou contre-proposition. Un accord doit être finalisé par vous ; les offres expirent après sept jours. Les effectifs doivent rester entre six et huit joueurs. En carrière, gagnez le championnat avant la fin de la saison 10. Une victoire apporte 10 XP et +2 de réputation ; une défaite, 3 XP et −1. Les objectifs offrent des points et de l’XP. Une réputation inférieure à 20 au bilan termine la carrière. Vous pouvez ensuite poursuivre en ligue libre.','Propose multiple players and manager points. AI replies after two days with acceptance, rejection or a counteroffer. Finalize accepted trades yourself; offers expire after seven days. Rosters must stay at six to eight. In career mode, win the championship by season 10. Wins earn 10 XP and +2 reputation; losses 3 XP and −1. Objectives reward points and XP. Reputation under 20 at season end ends the career. You may then continue in open league.','Propón jugadores y puntos. La IA responde tras dos días con aceptación, rechazo o contraoferta. Debes finalizar los acuerdos; caducan tras siete días. Las plantillas siguen entre seis y ocho. En carrera gana el título antes del final de temporada 10. Victoria: 10 XP y +2 reputación; derrota: 3 XP y −1. Los objetivos dan puntos y XP. Menos de 20 reputación al final termina la carrera; puedes continuar en liga libre.')],
[tr('08 / Sauvegardes et statistiques','08 / Saves and statistics','08 / Partidas y estadísticas'),tr('Chaque action sauvegarde la partie dans ce navigateur, y compris un match en cours. Exportez un fichier pour conserver une copie ou changer d’appareil. L’importation concerne uniquement cette nouvelle version. AVG = coups sûrs / présences officielles (les retraits au bâton comptent, les buts sur balles non). ERA reste normalisée sur neuf manches ; WHIP = (buts sur balles + coups sûrs accordés) / manches lancées. Les archives préservent les classements, fiches, résultats par manche et faits saillants.','Every action saves in this browser, including games in progress. Export a file for a backup or another device. Imports support this new version only. AVG = hits / at bats (strikeouts count, walks do not). ERA uses nine innings; WHIP = (walks + hits allowed) / innings pitched. Archives preserve standings, player cards, inning results and highlights.','Cada acción guarda en este navegador, incluso los partidos en curso. Exporta para conservar una copia o cambiar de dispositivo. Solo se importan partidas de esta versión. AVG = hits / turnos oficiales (ponches sí, bases por bolas no). ERA usa nueve entradas; WHIP = (bases por bolas + hits permitidos) / entradas lanzadas. El archivo conserva clasificaciones, fichas, resultados y jugadas destacadas.')],
[tr('09 / Développement et agents libres','09 / Development and free agents','09 / Desarrollo y agentes libres'),tr("Les gains conservent 60 % de leurs chances à 0 match, 80 % à 10 matchs et 100 % dès 20 matchs de saison régulière, avec une évolution linéaire entre ces seuils. Les séries ne donnent pas de bonus. Les anciens résultats sans bilan individuel utilisent une estimation du temps de jeu.\n\nUn joueur sans équipe cumule un bilan sans contrat à chaque intersaison. Dès le deuxième, il perd un point dans un attribut aléatoire. Avant 25 ans, cette perte n’a que 50 % de chances de s’appliquer, et chaque régression ordinaire a 50 % de chances d’être annulée. Une signature remet le compteur à zéro.\n\nLa retraite reste inchangée : après le test habituel, un agent libre subit un second test cumulant 15 points de pourcentage par bilan sans contrat, +15 à 27–29 ans ou +25 dès 30 ans, et +25 si son total est inférieur à 28/50, sinon +15 sous 32/50. Ce second risque est plafonné à 90 %.","Growth retains 60% of its chances at 0 games, 80% at 10 and 100% from 20 regular-season games, linearly between thresholds. Playoffs add no bonus. Older games without box scores use estimated participation.\n\nUnsigned players accumulate one free-agent review per offseason. From the second, one random skill loses a point. Before age 25 this loss has a 50% chance, and each ordinary negative change has a 50% chance to be cancelled. Signing resets the counter.\n\nRetirement is unchanged: after the ordinary check, free agents face a second check adding 15 percentage points per unsigned review, +15 at 27–29 or +25 from 30, and +25 below 28/50 total or otherwise +15 below 32/50. This second risk is capped at 90%.","Las mejoras conservan el 60% de sus opciones a 0 partidos, 80% a 10 y 100% desde 20 partidos regulares, de forma lineal. Las eliminatorias no dan bonificación; resultados antiguos sin resumen individual estiman la participación.\n\nCada cierre sin equipo suma un año libre. Desde el segundo se pierde un punto aleatorio. Antes de 25 años, esta pérdida tiene un 50% de probabilidad y cada cambio negativo ordinario puede anularse con un 50%. Fichar reinicia el contador.\n\nLa retirada no cambia: tras el sorteo habitual, otro suma 15 puntos porcentuales por cierre libre, +15 a los 27–29 o +25 desde 30, y +25 bajo 28/50 o, si no, +15 bajo 32/50. Máximo de este segundo riesgo: 90%.")],
[tr("10 / Gagner les derniers points","10 / Earning the last points","10 / Ganar los últimos puntos"),tr("Après le profil et le temps de jeu, chaque point gagné a une chance de réussite de 100 % jusqu’à 6, 80 % de 6 à 7, 55 % de 7 à 8, 25 % de 8 à 9 et 8 % de 9 à 10. Les gains multiples sont testés point par point et s’arrêtent au premier échec. Il n’y a plus de filtre initial de 70 %.","After career form and playing time, each gained point succeeds with 100% probability up to 6, 80% from 6 to 7, 55% from 7 to 8, 25% from 8 to 9 and 8% from 9 to 10. Multiple gains stop at the first failed point. The initial 70% filter is removed.","Tras el perfil y la participación, cada punto ganado tiene una probabilidad del 100% hasta 6, 80% de 6 a 7, 55% de 7 a 8, 25% de 8 a 9 y 8% de 9 a 10. Las mejoras múltiples se detienen al primer fallo. Se elimina el filtro inicial del 70%.")],
[tr("11 / Conserver les notes élevées","11 / Maintaining high ratings","11 / Mantener notas altas"),tr("Uniquement pendant la phase de déclin de sa carrière, chaque attribut subit après l’évolution ordinaire un risque supplémentaire de perdre 1 point : aucun à 5 ou moins, puis 5 / 10 / 15 / 20 / 25 % aux notes 6 / 7 / 8 / 9 / 10. La note après développement détermine ce risque. Cette perte ne s’applique pas pendant le développement ou le sommet. Les pertes ordinaires et celles des agents libres peuvent se cumuler. Le bilan affiche les changements nets, une seule fois par saison.","Only during the career decline phase, each skill faces an extra chance to lose 1 point after ordinary development: none at 5 or below, then 5 / 10 / 15 / 20 / 25% at ratings 6 / 7 / 8 / 9 / 10. The post-development rating sets the risk. Growth and peak phases are exempt. Ordinary and free-agent losses can stack. The review shows net changes, once per season.","Solo en la fase de declive, cada atributo tiene un riesgo adicional de perder 1 punto tras el desarrollo: ninguno con 5 o menos; 5 / 10 / 15 / 20 / 25% para 6 / 7 / 8 / 9 / 10. Se usa la nota tras el desarrollo. No se aplica durante desarrollo o apogeo. Las pérdidas ordinarias y de agentes libres pueden acumularse. El balance muestra cambios netos una vez por temporada.")],
[tr("12 / Un talent exceptionnel à la création","12 / Exceptional starting talent","12 / Talento excepcional inicial"),tr("Une note initialement générée à 10 n’a que 20 % de chances de rester à 10. Sinon, elle devient 9 et le point est transféré à un attribut inférieur à 9. Le total de talent du grade est conservé. Cette règle concerne tous les nouveaux joueurs. Atteindre 10 reste possible par progression.","A rating initially generated at 10 has a 20% chance to remain at 10. Otherwise it becomes 9 and the point is transferred to an attribute below 9. The grade’s total talent budget is preserved. This applies to all new players. Development can still raise a rating to 10.","Una nota generada inicialmente en 10 tiene un 20% de probabilidad de mantenerse. Si no, pasa a 9 y el punto se transfiere a un atributo inferior a 9. Se conserva el talento total del grado. Se aplica a todos los jugadores nuevos. La progresión permite alcanzar 10.")]
];
sections.push(
 [tr('13 / Lexique des attributs et statistiques','13 / Skills and statistics reference','13 / Referencia de atributos y estadísticas'),Object.keys(HELP).map(k=>`${k.toUpperCase()} — ${helpText(k)}`).join('\n\n')],
 [tr('14 / Repêchage, observation et favoris','14 / Draft, scouting and favorites','14 / Draft, observación y favoritos'),tr('Départ : 6 équipes vides, 60 joueurs, 8 rondes en serpentin, 48 choix obligatoires. Entre les saisons : 24 recrues, 2 rondes dans l’ordre inverse du classement régulier, sans inversion entre rondes. On peut passer chaque tour annuel, y compris les deux; aucun tour de départ ne peut être passé. Un effectif plein doit libérer un joueur avant de confirmer un choix. Les recrues non choisies deviennent agents libres. Dès l’automne, Repêchage montre le même groupe qui sera disponible au printemps. Le panneau Prochain tour affiche l’équipe et la ronde suivantes. Les annonces ralentissent les sélections et bloquent les doubles clics. Gestion d’équipe reste consultable pendant le repêchage initial. Le journal personnel garde la ronde et le numéro de choix global. Une étoile près du nom ajoute ou retire un favori. Le filtre ★ ne montre que les favoris de la liste courante; la page Favoris réunit tous les joueurs suivis, même retraités. Ces favoris sont personnels, propres à cette partie et enregistrés dans ce navigateur.','Initial draft: six empty teams, 60 players and eight snake rounds; 48 mandatory picks. Annual draft: 24 rookies, two rounds in reverse standings order; either or both picks may be skipped. Full rosters must release a player to draft. Undrafted players become free agents. Autumn scouting shows the same spring class. Up next shows the next team and round. Pick announcements prevent double clicks. Team rosters remain available during the initial draft. Player journals record round and overall pick. Stars mark favorites; the star filter narrows the current list, while Favorites shows everyone you follow. Favorites are personal to this game and browser.','Draft inicial: seis equipos, 60 jugadores y ocho rondas serpiente obligatorias. Draft anual: 24 novatos y dos rondas inversas a clasificación; se puede pasar ambos turnos. Plantillas llenas liberan un jugador. No elegidos quedan libres. Desde otoño se observa la misma clase de primavera. Se muestran equipo y ronda siguientes, anuncios y bloqueo de doble clic. Equipo consultable durante draft inicial. Historial con ronda y elección global. Estrellas guardan favoritos personales de esta partida en este navegador.')],
 [tr('15 / Trophées et intersaison','15 / Awards and offseason','15 / Premios y entretemporada'),tr('Étape 1 : les trophées défilent avec Continuer. Chaque gagnant montre ses attributs et résultats de saison; les deuxième et troisième montrent portrait, nom et indice. Un seul gagnant par prix, cumul possible. Pas de recrue de l’année en saison 1. Attaque = simples + 2 doubles + 3 triples + 4 circuits + 0,7 BB + 0,5 R + 0,6 RBI − 0,3 SO. Défense = retraits en réception + retraits sur relais − 2 erreurs. Lanceur = 0,4 retraits lancés + SO − 1,5 points mérités − 0,5 coups sûrs concédés − 0,5 BB. MVP = attaque + 0,5 défense + 0,5 max(0, lanceur). Minimums : 30 AB au bâton, 20 occasions en défense, 18 manches au lancer; MVP/recrue : 30 présences avec BB ou 18 manches. MVP des séries : 6 présences ou 3 manches. Égalité : participation, puis identifiant. Étape 2 : progression nette et retraites, sans doubler les retraités dans le tableau de progression. Les clubs sont remis à au moins six joueurs. Confirmer ouvre la saison suivante et son repêchage; les archives restent accessibles. Le prix de progression est attribué après le développement et figure aux archives.','Step 1 presents each award, winner statistics and the top-three podium. One winner per award; multiple awards per player allowed. Rookie award starts in season 2. Bat index: total bases + .7 BB + .5 R + .6 RBI − .3 SO. Glove: catching/throwing outs − 2 errors. Pitcher: .4 pitching outs + SO − 1.5 ER − .5 hits allowed − .5 walks. MVP: bat + half glove + half positive pitcher score. Qualifications: 30 AB, 20 fielding chances, or 18 pitching innings for respective awards; MVP/rookie: 30 PA or 18 IP; playoff MVP: 6 PA or 3 IP. Ties use participation then ID. Step 2 shows development and separate retirements. Confirmation opens the next season’s draft. Most improved is awarded after development and stored in archives.','Paso 1: premios, estadísticas del ganador y podio de tres. Un ganador por premio, acumulación permitida. Novato desde temporada 2. Paso 2: desarrollo y retiradas separadas. Confirmar abre la próxima temporada y el draft. Los criterios completos están en las tarjetas de premios del archivo.')],
 [tr('16 / Multijoueur et observation','16 / Multiplayer and spectating','16 / Multijugador y observación'),tr('L’hôte crée le salon et partage les invitations personnelles. Jusqu’à six participants; les autres équipes sont NPC. Les participants sont fixés au lancement. Chaque joueur prépare son équipe et confirme Prêt; l’hôte confirme ensuite le jour ou l’étape. Les matchs entre humains nécessitent leur présence; l’équipe à domicile contrôle la lecture. Un joueur peut demander une pause ou autoriser l’IA en son absence. La sauvegarde complète reste chez l’hôte. Les vitesses 1×, 2× et 4× changent le rythme de lecture, jamais les probabilités. Les actions ont un temps minimal lisible et les circuits/triples une bannière de six secondes minimum. Le mode pas à pas permet de lire chaque action et ses calculs.','The host creates the room and shares personal invitations. Up to six participants; other teams are NPCs. Each participant confirms Ready before the host advances. Human matches require presence; the home team controls playback. Participants can request a pause or delegate to AI. Saves stay with the host. Playback speeds never change probabilities; actions have a minimum readable duration and major banners last at least six seconds. Step mode shows each action and its calculations.','El anfitrión comparte invitaciones personales, hasta seis participantes. Todos confirman Listo antes de avanzar. Partidos humanos requieren presencia; local controla reproducción. Se puede pedir pausa o delegar a IA. Guardado en anfitrión. Velocidad no cambia probabilidades; banners duran al menos seis segundos y existe modo paso a paso.')]
);
sections.push([tr('17 / Rotation des lanceurs','17 / Pitching rotation','17 / Rotación de lanzadores'),tr('Dans Gestion d’équipe, choisissez de 2 à 4 lanceurs et leur ordre. Les équipes NPC et les anciennes sauvegardes commencent avec trois lanceurs classés par THR. L’alignement automatique part du prochain dans l’ordre et retient le premier avec au moins 60 d’énergie. Si tous ont moins de 60, il prend celui qui a le plus d’énergie; à égalité, l’ordre de rotation départage. Les cinq autres titulaires sont choisis selon leur énergie et leurs talents. Les autres membres de la rotation peuvent jouer à une autre position. Après le match, le tour passe au suivant du lanceur réellement utilisé, même en manuel s’il appartient à la rotation. Consulter le rapport ou refaire l’alignement ne consomme aucun tour. La rotation continue en séries et la saison suivante. Un départ est remplacé automatiquement pour conserver sa taille.','Choose 2–4 pitchers in order in Team management. NPC teams and older saves start with three pitchers ranked by THR. Auto lineup cycles from the next pitcher and selects the first with at least 60 energy. If all are below 60, the highest energy wins; ties follow rotation order. Five other starters are selected by energy and skills. Other rotation members can field elsewhere. After the game, the next turn follows the actual pitcher, including a manual starter in the rotation. Reports and repeated auto lineup clicks never consume a turn. Rotation continues through playoffs and seasons. Departures are automatically replaced to maintain its size.','Elige de 2 a 4 lanzadores en orden en Gestión de equipo. NPC y partidas antiguas comienzan con tres por THR. La alineación automática elige el primero desde el próximo turno con al menos 60 de energía. Si todos tienen menos de 60, elige al de mayor energía; los empates siguen el orden. Los otros cinco titulares se eligen por energía y talento. Los demás lanzadores pueden ocupar otra posición. El turno avanza después del partido desde el lanzador real, también en modo manual si pertenece a la rotación. Consultas y alineaciones no consumen turnos. La rotación continúa en eliminatorias y temporadas; las bajas se sustituyen automáticamente.')]);
sections.push([tr('17 / Formes de carrière','17 / Career profiles','17 / Perfiles de carrera'),E.FORMS.map(form=>formName(form)+' — '+careerDescription({form})).join('\n\n')],[tr('18 / Trophées et valeur d’échange','18 / Trophies and trade value','18 / Premios y valor de intercambio'),tr("Les cinq prix suivants ajoutent un bonus de valeur d’échange : MVP +3; meilleur frappeur, lanceur ou défenseur +2 chacun; recrue de l’année +1,5. Le bonus vaut 100 % pour la dernière saison terminée, 50 % pour la précédente et 25 % pour celle d’avant, puis disparaît. Il s’applique dès la remise du prix, sans nouvelle baisse au printemps suivant. Les bonus se cumulent jusqu’à +6. Les podiums et les autres distinctions ne donnent pas de bonus. Les décimales sont conservées dans les calculs; seule la valeur affichée est arrondie.","Five awards increase trade value: MVP +3; best batter, pitcher or defender +2 each; rookie of the year +1.5. Bonuses retain 100% for the last completed season, 50% for the previous one and 25% for the one before, then expire. They apply immediately at awards, without another reduction the following spring. Combined cap: +6. Podium places and other awards give no bonus. Calculations keep fractions; only the displayed value is rounded.","Cinco premios aumentan el valor: MVP +3; mejor bateador, lanzador o defensor +2; novato +1,5. Conservan 100% para la última temporada terminada, 50% para la anterior y 25% para la precedente; después caducan. Se aplican al entregar el premio, sin otra reducción la primavera siguiente. Máximo conjunto +6. Podios y otras distinciones no dan bono. Los cálculos conservan decimales; se redondea solo el valor mostrado.")]);
sections.push([tr('19 / Erreurs défensives','19 / Fielding errors','19 / Errores defensivos'),tr('Chaque balle dirigée vers un défenseur déclenche un seul tirage d’erreur. Le risque vaut max(0,6 % ; 1,5 / (1 + CAT + SPE)²), avec les capacités après fatigue. Les chances diminuent avec CAT et SPE. Le pourcentage défensif utilise uniquement les retraits en réception, les retraits sur relais et les erreurs. Les résultats passés restent inchangés; le pourcentage se recalcule depuis les compteurs enregistrés.','Each ball directed at a fielder triggers one error roll. Risk is max(0.6%; 1.5 / (1 + CAT + SPE)²), using fatigue-adjusted skills. Higher CAT and SPE reduce risk. Fielding percentage uses only catching outs, throwing outs and errors. Past results stay unchanged; the percentage is recalculated from recorded counters.','Cada bola dirigida a un defensor genera un único sorteo de error. Riesgo: max(0,6%; 1,5 / (1 + CAT + SPE)²), con atributos ajustados por fatiga. CAT y SPE reducen el riesgo. El porcentaje usa outs por recepción, por tiro y errores. Los resultados anteriores se conservan; se recalcula el porcentaje con sus contadores.')]);
const normalize=v=>v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),query=normalize(wikiQuery),found=sections.map(([head,body],i)=>({head,body,i})).filter(x=>!query||normalize(x.head+' '+x.body).includes(query));
return title(tr('Wiki des règles','Rules wiki','Wiki de reglas'),!S?go(t('back'),'menu'):'')+`<label class="wiki-search">${tr('Rechercher dans les règles','Search the rules','Buscar en las reglas')}<input id="wiki-search" type="search" placeholder="CON, talent, repêchage, séries…" value="${esc(wikiQuery)}"></label><p role="status">${found.length} / ${sections.length} ${tr('rubriques','articles','artículos')}</p><nav class="wiki-toc">${found.map(x=>`<a href="#rule-${x.i}">${esc(x.head)}</a>`).join('')}</nav><div class="rules">${found.map(x=>`<article id="rule-${x.i}">${panel(x.head,x.body.split('\n\n').map(p=>`<p>${esc(p)}</p>`).join(''))}</article>`).join('')||empty(t('no_results'))}</div>`;
}

let previousProfile={route:'team',params:{},filter:''},profileIds=[],playSpeed=1200;
function careerDescription(p){const descriptions={"Normal": ["Développement jusqu’à 25 ans; sommet de 26 à 29 ans; déclin dès 30 ans.", "Growth through 25; peak at 26–29; decline from 30.", "Desarrollo hasta 25; apogeo a los 26–29; declive desde 30."], "Régulier": ["Petits gains jusqu’à 27 ans; sommet de 28 à 31 ans; déclin lent dès 32 ans.", "Small gains through 27; peak at 28–31; slow decline from 32.", "Pequeñas mejoras hasta 27; apogeo a los 28–31; declive lento desde 32."], "Jeune Étoile": ["Forte progression avant 23 ans; sommet de 23 à 28 ans; déclin dès 29 ans.", "Fast growth before 23; peak at 23–28; decline from 29.", "Crecimiento rápido antes de 23; apogeo a los 23–28; declive desde 29."], "Tardif": ["Peu de gains avant 25 ans; forte progression de 25 à 29 ans; sommet de 30 à 32 ans; déclin dès 33 ans.", "Little growth before 25; fast growth at 25–29; peak at 30–32; decline from 33.", "Pocas mejoras antes de 25; crecimiento fuerte a los 25–29; apogeo a los 30–32; declive desde 33."], "Vétéran": ["Progression modérée jusqu’à 25 ans; long sommet de 26 à 33 ans; déclin lent dès 34 ans.", "Moderate growth through 25; long peak at 26–33; slow decline from 34.", "Crecimiento moderado hasta 25; apogeo largo a los 26–33; declive lento desde 34."], "Éclair": ["Progression explosive jusqu’à 22 ans; sommet de 23 à 25 ans; déclin rapide dès 26 ans.", "Explosive growth through 22; peak at 23–25; fast decline from 26.", "Crecimiento explosivo hasta 22; apogeo a los 23–25; declive rápido desde 26."], "Faible": ["Gains rares jusqu’à 25 ans; sommet de 26 à 28 ans; déclin dès 29 ans.", "Rare gains through 25; peak at 26–28; decline from 29.", "Mejoras raras hasta 25; apogeo a los 26–28; declive desde 29."]};return tr(...(descriptions[p.form]||descriptions.Normal));}
function developmentNote(src,p){const part=E.seasonParticipation(src),games=part.counts.get(p.id)||0;return `<p class="development-note">${tr('Matchs joués en saison régulière','Regular-season appearances','Partidos de temporada regular')}${part.estimated?' ≈':''} : <b>${games}</b> · ${tr('Chances de gain conservées','Growth chances retained','Opciones de mejora conservadas')} : <b>${n(E.developmentFactor(games)*100,1)} %</b></p>${!p.retired&&!src.teams.some(t=>t.roster.includes(p.id))?`<p>${tr('Bilans comme agent libre','Free-agent year-end reviews','Cierres como agente libre')} : ${p.freeSeasons??0}</p>`:''}`;}
function profileNavigation(){const i=profileIds.indexOf(params.id);if(i<0)return '';return `<nav class="actions profile-navigation" aria-label="${tr('Parcourir les joueurs','Browse players','Recorrer jugadores')}">${btn(tr('← Précédent','← Previous','← Anterior'),'profile-step','data-step="-1"','',i===0)}<span>${i+1} / ${profileIds.length}</span>${btn(tr('Suivant →','Next →','Siguiente →'),'profile-step','data-step="1"','',i===profileIds.length-1)}</nav>`;}
let lastViewKey='';
function render(){const viewKey=JSON.stringify([S?.id,route,params,archiveId,view,teamRotation,teamPreferences]),layout=viewKey===lastViewKey?captureLayout(document):null;const noticeGame=S?.id+':'+S?.user;if(draftNoticeGame!==noticeGame){clearTimeout(draftNoticeTimer);draftNoticeTimer=null;draftNotices=[];draftPending=false;draftLockUntil=0;draftNoticeGame=noticeGame;}if(S?.online?.phase==='lobby'&&!['online','rules','saves'].includes(route))route='online';if(S){E.ensureSeason(S);E.ensureLogos(S);E.ensurePortraits(S);E.ensureAttributeHistory(S);}if(S?.draft?.kind==='initial'&&S.online?.phase!=='lobby'&&!['draft','team','favorites','profile','rules','saves','online'].includes(route)){route='draft';params={};archiveId=null;}tutorialSync();document.documentElement.lang=lang;document.body.classList.toggle('no-motion',!prefs.motion);const pages={favorites:favoritesPage,online:onlinePage,dynasty:dynastyPage,prematch:preMatchPage,league:leaguePage,menu,new:newForm,saves:savePage,dashboard,team:teamPage,profile,calendar,playoffs:playoffPage,offseason:offseasonPage,standings:()=>title(t('standings'))+standingTable(dataSource()),leaders,free:()=>title(t('free'))+panel(t('free'),playerTools()+playerTable(S.free,S,'sign')),draft:draftPage,archives:archivePage,season:seasonPage,trades,'trade-new':tradeForm,watch,match:matchSummary,rules};if(!S&&!['menu','new','saves','rules','online'].includes(route))route='menu';const banner=S?.online?.phase==='lobby'?'':championshipBanner(),consent=timeVoteDialog(),blocking=banner||consent;app.innerHTML=(blocking?'<div inert>':'')+shell(pages[route]?.()||menu())+(blocking?'</div>':'')+banner+draftNoticeHTML()+consent;onlineDecorate();tutorialDecorate();if(layout)restoreLayout(document,layout);lastViewKey=JSON.stringify([S?.id,route,params,archiveId,view,teamRotation,teamPreferences]);if(consent)document.querySelector('.time-vote-dialog .primary')?.focus?.();decorateDraftLock();if(lastRenderedRoute!==route&&['watch','match'].includes(route))document.querySelector('.match-board')?.scrollIntoView?.({block:'start',behavior:'instant'});lastRenderedRoute=route;juiceAfterRender();if(banner&&!consent)app.querySelector?.('[data-action="champion-dismiss"]')?.focus?.();}
let scene=null,sceneTimer=null;
function clearScene(){clearTimeout(sceneTimer);sceneTimer=null;scene=null;}
function showScene(event,previous,m){
 clearScene();const reduced=!prefs.motion||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
 const duration=reduced?100:Math.max(850,Math.min(2400,playSpeed*1.6));
 scene={matchId:m.id,event,previous,duration,startedAt:Date.now()};
 holdUntil=Math.max(holdUntil,Date.now()+duration);
 sceneTimer=setTimeout(()=>{scene=null;sceneTimer=null;if(route==='watch')render();},duration);
}
let moment=null,momentTimer=null,holdUntil=0,pendingSummary=null;
function clearMoment(){clearTimeout(momentTimer);momentTimer=null;moment=null;holdUntil=0;pendingSummary=null;}
function stopPlay(){clearInterval(replayTimer);replayTimer=null;}
function sound(e){if(e.type!=='HR')juiceTone(e.runs?'ok':'click');}
function showMoment(e,previous,m,finished=false){
 const kind=matchMoment(e,previous,finished);if(!kind)return;
 clearMoment();const defensive=kind==='double-play',tid=kind==='victory'?m.winner:defensive?(e.half?m.away:m.home):(e.half?m.home:m.away);
 moment={kind,event:e,team:tid,finished};holdUntil=Date.now()+6000+(scene?.duration||0);
 if(finished)pendingSummary=m.id;
 momentTimer=setTimeout(()=>{const summary=pendingSummary;clearMoment();if(route!=='watch')return;if(summary){stopPlay();navigate('match',{id:summary});}else render();},6000+(scene?.duration||0));
}
function momentBanner(m){if(!moment)return '';const tm=E.team(dataSource(),moment.team),e=moment.event,colors=E.logoById(tm.logo).colors,accent=tm.logo==='wolf'?colors[2]:colors[1];
 return `<div class="moment-overlay moment-${moment.kind}" role="status" aria-live="polite" style="--moment-main:${colors[0]};--moment-accent:${accent};--moment-ink:${onColor(colors[0])};--moment-button-ink:${onColor(accent)}"><div class="moment-ribbon"><div class="moment-crest">${logoImage(tm.logo)}</div><small>${esc(tm.name)}</small><strong>${MOMENT_LABELS[moment.kind][['fr','en','es'].indexOf(lang)]}</strong><span>${esc(moment.kind==='double-play'?e.defender:moment.kind==='victory'?tr('Match terminé','Final score','Resultado final'):e.batter)}</span><b class="moment-score">${e.score.join(' — ')}${e.runs?' · +'+e.runs:''}</b>${moment.finished&&moment.kind!=='victory'?`<small>${tr('Victoire !','Victory!','¡Victoria!')}</small>`:''}<div class="moment-duration"></div>${btn(tr('Continuer','Continue','Continuar'),'moment-skip','','small')}</div></div>`;
}
function playStep(){
 if(Date.now()<holdUntil)return;
 if(S.live){const id=S.live.id,previous=S.live.events.at(-1);change(()=>{const e=E.stepMatch(S),finished=!S.live,m=finished?S.schedule.find(x=>x.id===id).result:S.live;sound(e);showScene(e,previous,m);showMoment(e,previous,m,finished);if(finished){stopPlay();params={id};replayIndex=m.events.length;}});
 }else{const m=matchData();if(m&&replayIndex<(m.events||[]).length){const previous=m.events[replayIndex-1],e=m.events[replayIndex++];sound(e);showScene(e,previous,m);showMoment(e,previous,m,replayIndex===m.events.length);}if(!m||replayIndex>=(m.events||[]).length)stopPlay();render();}
}

function replacement(id,draft=false){if(E.team(S).roster.length<8){change(()=>draft?E.draftPick(S,id):E.sign(S,id));return;}modal.innerHTML=`<h2>${t('choose_cut')}</h2><form id="replace-form"><input type="hidden" name="id" value="${id}"><input type="hidden" name="draft" value="${draft}"><label>${t('cut')}<select name="cut">${E.team(S).roster.map(pid=>`<option value="${pid}">${esc(S.players[pid].name)} · ${E.total(S.players[pid])}/50</option>`).join('')}</select></label><div class="actions"><button class="btn primary">${t('confirm')}</button>${btn(t('cancel'),'close')}</div></form>`;modal.showModal();}
async function runLong(fn){if(busy)return;busy=true;stopPlay();clearMoment();clearScene();notify(t('loading'));await new Promise(r=>setTimeout(r,30));change(fn);busy=false;}
document.addEventListener('click',ev=>{const el=ev.target.closest('button');if(el&&!el.disabled)juiceTone('click');},true);
document.addEventListener('click',async ev=>{let el=ev.target.closest('[data-action]');if(!el||el.disabled)return;ev.preventDefault();let d=el.dataset;try{switch(d.action){
case 'tutorial-done':if(tutorialTip()?.[0]===d.id){tutorialDone(d.id);persist();render();}break;
case 'tutorial-minimize':if(tutorialState()?.enabled){S.tutorial.minimized=true;persist();render();}break;
case 'tutorial-expand':if(tutorialState()?.enabled){S.tutorial.minimized=false;persist();render();}break;
case 'tutorial-stop':if(tutorialState()){S.tutorial.enabled=false;persist();render();}break;
case 'tutorial-resume':if(S&&!S.online){S.tutorial={version:1,done:[],...tutorialState(),enabled:true,minimized:false};persist();render();}break;
case 'tutorial-target':{const selector=tutorialTip()?.[4],target=selector&&document.querySelector(selector);target?.scrollIntoView?.({block:'center',behavior:prefs.motion?'smooth':'instant'});target?.focus?.({preventScroll:true});break;}
case 'favorite':{const ids=new Set(favoriteIds());ids.has(d.id)?ids.delete(d.id):ids.add(d.id);localStorage.setItem(favoriteKey(),JSON.stringify([...ids]));render();for(const el of document.querySelectorAll('.favorite'))if(el.dataset.id===d.id)juiceAnimate(el,[{transform:'scale(.7) rotate(-15deg)'},{transform:'scale(1.3) rotate(10deg)',offset:.55},{transform:'scale(1) rotate(0)'}],360);juiceTone('ok');break;}
case 'rotation-tab':teamRotation=true;teamPreferences=false;render();break;
case 'preferences-tab':teamPreferences=true;teamRotation=false;render();break;
case 'rotation-next':change(()=>E.setNextPitcher(S,d.id));break;
case 'award-skip':awardCursor[S.id+':'+S.season+':'+S.user]=Number.MAX_SAFE_INTEGER;render();break;
case 'favorites-filter':favoritesOnly=!favoritesOnly;render();break;
case 'stat-help':modal.innerHTML=`<h2>${tr('Comprendre cette statistique','About this statistic','Sobre esta estadística')}</h2><p>${esc(helpText(d.key)).replaceAll('\n','<br>')}</p>${btn(t('close'),'close')}`;modal.showModal();break;
case 'award-next':awardCursor[S.id+':'+S.season+':'+S.user]=(awardCursor[S.id+':'+S.season+':'+S.user]||0)+1;render();break;
case 'award-replay':awardCursor[S.id+':'+S.season+':'+S.user]=0;render();break;
case 'nav':if(d.to==='dashboard')archiveId=null;if(d.to==='saves'||d.to==='menu'){await saveQueue;try{savedGames=await Store.list();}catch{}}if(el.closest('.sidebar')||el.closest('.masthead'))archiveId=null;navigate(d.to,d.id?{id:d.id}:{});break;
case 'language':setLang(d.lang);render();break;
case 'load':case 'backup':stopPlay();await saveQueue;S=await Store.load(d.id,d.action==='backup');if(S.online){await openOnlineSave(S);break;}archiveId=null;navigate(S.live?'watch':S.draft?'draft':'dashboard');break;
case 'delete':confirmBox(t('confirm_delete'),async()=>{await saveQueue;await Store.remove(d.id);savedGames=await Store.list();render();});break;
case 'save':if(await persist())notify(t('saved'));break;
case 'export':Store.download(S);break;
case 'quit':stopPlay();if(await persist()){S=null;archiveId=null;navigate('menu');}break;
case 'close':modal.close();break;
case 'profile':previousProfile={route,params:{...params},filter};profileIds=route==='team'?sortedPlayers(E.team(dataSource(),params.id||S.user).roster,dataSource()).map(p=>p.id):[];profileTab='career';navigate('profile',{id:d.id});break;
case 'profile-step':{const i=profileIds.indexOf(params.id),step=Number(d.step),id=profileIds[i+step];if(i>=0&&[-1,1].includes(step)&&id){params={id};render();if(['watch','match'].includes(route))document.querySelector('.match-board')?.scrollIntoView?.({block:'start',behavior:'instant'});else window.scrollTo({top:0,behavior:'instant'});}break;}
case 'profile-back':navigate(previousProfile.route,previousProfile.params);filter=previousProfile.filter||'';render();break;
case 'audit':{let issues=E.auditStats(S);modal.innerHTML=`<h2>${tr('Contrôle des statistiques','Statistics check','Control de estadísticas')}</h2><p>${issues.length?esc(issues.join(' · ')):tr('Les compteurs de la ligue sont cohérents : présences, coups sûrs, retraits, buts sur balles et points.','League counters are consistent: at bats, hits, outs, walks and runs.','Los contadores de la liga son coherentes: turnos, hits, eliminados, bases por bolas y carreras.')}</p>${btn(t('close'),'close')}`;modal.showModal();break;}
case 'view-team':navigate('team',{id:d.id});break;
case 'sort':sortDir=sortKey===d.key?-sortDir:['name','age','grade','form','era','whip'].includes(d.key)?1:-1;sortKey=d.key;render();break;
case 'stats-scope':statScope=d.scope;render();break;
case 'offseason-next':{const advance=()=>{window.scrollTo(0,0);change(()=>{E.advanceOffseason(S);if(S.draft){route='draft';params={};archiveId=null;}});};if(S.offseason.stage==='awards')advance();else confirmBox(tr('Terminer la saison et commencer la suivante avec le repêchage ?','End this season and start the next draft?','¿Terminar la temporada y comenzar el próximo draft?'),advance);break;}
case 'view-tab':teamPreferences=false;teamRotation=false;view=d.tab;render();break;
case 'profile-tab':profileTab=d.tab;render();break;
case 'auto-align':change(()=>{E.assertEditable(S);E.autoAlign(S,E.team(S));tutorialDone('lineup');});break;
case 'cut':confirmBox(t('confirm_cut'),()=>change(()=>E.cut(S,d.id)));break;
case 'sign':replacement(d.id);break;
case 'choose':if(draftBusy())break;replacement(d.id,true);break;
case 'draft-skip':if(draftBusy())break;change(()=>E.skipDraftTurn(S));break;
case 'draft-auto-one':if(draftBusy())break;change(()=>E.draftPick(S,null,null,true));break;
case 'draft-next':if(draftBusy())break;change(()=>E.draftPick(S,null,null,true));break;
case 'draft-until-user':if(draftBusy())break;change(()=>E.autoDraft(S));break;
case 'draft-auto':if(draftBusy())break;confirmBox(t('confirm_draft'),()=>change(()=>E.autoDraft(S,true)));break;
case 'watch-start':navigate('prematch',{id:d.id,mode:'watch'});break;
case 'pregame-watch':change(()=>{E.startMatch(S,d.id);route='watch';params={id:d.id};});break;
case 'pregame-simulate':await runLong(()=>{E.simulateMatch(S,d.id);route='match';params={id:d.id};});break;
case 'simulate':confirmBox(tr('Simuler cette partie ?','Simulate this game?','¿Simular este partido?')+'<p>'+tr('Alignement','Lineup','Alineación')+' : <b>'+ (E.team(S).auto?tr('Automatique','Automatic','Automática'):tr('Manuel','Manual','Manual'))+'</b></p>',()=>runLong(()=>{E.simulateMatch(S,d.id);route='dashboard';params={};}));break;
case 'next':change(()=>{let day=S.day;E.nextDay(S);if(S.offseason)route='offseason';});break;
case 'month':confirmBox(t('confirm_month'),()=>runLong(()=>{E.simulatePeriod(S);route=S.offseason?'offseason':'dashboard';}));break;
case 'champion-dismiss':if(S.online)onlineChampionSeen.add(S.id+':'+S.season);S.presentation={...S.presentation,championSeen:S.season};persist();navigate(S.playoffs?.winner===S.user&&S.mode==='career'?'dynasty':'dashboard');break;
case 'continue-free':change(()=>{S.mode='free';S.careerResult=null;route='dashboard';});break;
case 'period':calendarPeriod=Number(d.period);render();break;
case 'leader-key':params.key=d.key;render();break;
case 'archive-open':archiveId=Number(d.season);render();break;
case 'archive-close':archiveId=null;render();break;
case 'match-open':navigate('match',{id:d.id});break;
case 'trade-tab':tradeTab=d.tab;render();break;
case 'offer-request':change(()=>{E.assertEditable(S);E.generateOffer(S);});break;
case 'trade-accept':confirmBox(t('accept')+' ?',()=>change(()=>E.acceptTrade(S,d.id)));break;
case 'trade-refuse':change(()=>E.refuseTrade(S,d.id));break;
case 'replay-start':navigate('watch',{id:d.id});break;
case 'play-toggle':if(replayTimer)stopPlay();else replayTimer=setInterval(playStep,playSpeed);render();break;
case 'play-step':stopPlay();playStep();break;
case 'play-finish':await runLong(()=>{let id=S.live.id;E.simulateMatch(S,id);route='match';params={id};});break;
case 'moment-skip':{const summary=pendingSummary;clearScene();clearMoment();if(summary)navigate('match',{id:summary});else render();break;}
case 'replay-reset':stopPlay();clearMoment();clearScene();replayIndex=0;render();break;
}}catch(e){notify(t(e.message),true);}});
document.addEventListener('submit',ev=>{ev.preventDefault();let f=ev.target,d=new FormData(f);switch(f.getAttribute('id')){case 'rotation-form':change(()=>{E.setPitchingRotation(S,d.getAll('pitcher').filter(Boolean));tutorialDone('rotation');});break;case 'new-form':{let name=d.get('team').trim(),manager=d.get('manager').trim();if(!name||!manager)return;stopPlay();S=E.newGame(name,manager,d.get('mode'),Date.now(),d.get('logo')||'wolf');S.tutorial={version:1,enabled:d.get('tutorial')==='on',minimized:false,done:[]};archiveId=null;view='talent';persist();navigate('draft');break;}case 'replace-form':if(d.get('draft')==='true'&&draftBusy())break;change(()=>{if(d.get('draft')==='true')E.draftPick(S,d.get('id'),d.get('cut'));else E.sign(S,d.get('id'),d.get('cut'));modal.close();});break;case 'trade-form':change(()=>{E.propose(S,d.get('to'),d.getAll('offered'),d.getAll('asked'),d.get('pay'),d.get('receive'));route='trades';tradeTab='sent';});break;}});
document.addEventListener('change',async ev=>{let el=ev.target;try{if(el.name==='logo'&&el.type!=='select-one'&&E.logoById(el.value)){selectedLogo=el.value;document.querySelector('.setup-art')?.style?.setProperty('--park-image',`url('./assets/parks/${selectedLogo}.webp')`);const input=document.querySelector('#new-form input[name="team"]')||document.querySelector('#online-create-form input[name="team"]');if(input)input.value=E.logoById(selectedLogo).teamName;document.querySelector('#team-theme').textContent=':root{'+themeTokens(selectedLogo)+'}';}if(el.id==='auto-toggle')change(()=>{E.assertEditable(S);E.team(S).auto=el.checked;});if(el.id==='development-team'&&S&&['offseason','season'].includes(route)){params={...params,developmentTeam:el.value};render();}if(el.id==='trade-team')navigate('trade-new',{to:el.value});if(el.id==='play-speed'){playSpeed=Number(el.value);if(replayTimer){stopPlay();replayTimer=setInterval(playStep,playSpeed);}}if(el.dataset.pref){prefs[el.dataset.pref]=el.checked;try{localStorage.setItem('slimball.preferences',JSON.stringify(prefs));}catch{}render();}if(el.id==='import-file'&&el.files[0]){if(el.files[0].size>30000000)throw Error('file_large');const imported=Store.decode(await el.files[0].text());confirmBox(tr('Charger cette partie importée ?','Load this imported game?','¿Cargar esta partida importada?'),()=>{stopPlay();if(imported.online){openOnlineSave(imported);return;}S=imported;archiveId=null;persist();navigate(S.live?'watch':S.draft?'draft':'dashboard');});}}catch(e){notify(t(e.message),true);}});
document.addEventListener('input',ev=>{if(ev.target.id==='player-search'){let pos=ev.target.selectionStart;filter=ev.target.value;render();let input=document.querySelector('#player-search');input.focus({preventScroll:true});input.setSelectionRange(pos,pos);}});
window.addEventListener('pagehide',()=>{stopPlay();clearMoment();clearScene();});
window.addEventListener('beforeunload',ev=>{if(saveFailed||pendingSaves){ev.preventDefault();ev.returnValue='';}});
const onlineChampionSeen=new Set();
let onlineView='create',onlineInvite=readInvitation(),onlineError='',onlineConnecting=false;
function updateSaveStatus(){const el=document.querySelector('#save-status');if(el){el.classList.toggle('unsaved',saveFailed);el.textContent=saveFailed?t('save_failed'):pendingSaves?t('saving'):t('saved');}}
async function saveOnline(state){pendingSaves++;updateSaveStatus();try{await Store.save(state);savedGames=await Store.list();saveFailed=false;}catch(e){saveFailed=true;throw Error(t('save_failed'));}finally{pendingSaves--;updateSaveStatus();}}
const ON=new OnlineClient({save:saveOnline,onError:message=>{onlineError=message;notify(message,true);},onStatus:()=>{const el=document.querySelector('#connection-status');if(el)el.textContent=ON.presence.includes('t0')?'Session connectée':'En attente du retour de l’hôte…';},onState:(state,actor,presence)=>{
 const old=S,oldLive=S?.live,oldRoute=route;S=MP.project(state,actor);if(S.online.timeNotice&&S.online.timeNotice.id!==old?.online?.timeNotice?.id)notify(S.online.timeNotice.message,true);
 if(state.online.phase==='lobby'||!MP.member(state,actor))route='online';
 else if(!old?.draft&&S.draft||old?.online?.phase==='lobby'||!old){route=S.draft?'draft':'dashboard';params={};}
 if(S.live&&(!oldLive||oldLive.id!==S.live.id)){stopPlay();clearMoment();route='watch';params={id:S.live.id};}
 else if(oldLive&&!S.live&&route==='watch'){const m=S.schedule.find(m=>m.id===oldLive.id)?.result;params={id:oldLive.id};if(m?.events?.length){const e=m.events.at(-1);replayIndex=m.events.length;showScene(e,oldLive.events.at(-1),m);showMoment(e,oldLive.events.at(-1),m,true);}else route='match';}
 if(oldLive&&S.live&&oldLive.events.length<S.live.events.length){const e=S.live.events.at(-1);sound(e);showScene(e,oldLive.events.at(-1),S.live);showMoment(e,oldLive.events.at(-1),S.live,false);}
 queueDraftNotices(old);
 const values=captureForms(document),focus=captureFocus(document);
 render();if(oldRoute===route){restoreForms(document,values);if(!document.querySelector('.time-vote-dialog,.championship-overlay'))restoreFocus(document,focus);}
}});
const isOnline=()=>!!S?.online;
const sendOnline=async(type,args={})=>{if(type==='draft'){if(draftBusy())return;args={...args,index:S.draft?.index};draftPending=true;decorateDraftLock();}try{await ON.send(type,args);}catch(e){notify(e.message,true);}finally{if(type==='draft'){draftPending=false;draftLockUntil=Date.now()+1600;setTimeout(()=>render(),1700);}}};
function onlineDayAction(){
 const o=S.online,m=E.userMatch(S),blocked=!ON.presence.includes(o.host)||!!o.vote;
 let action=S.draft?go('Continuer le repêchage','draft','','primary'):S.live?go('Reprendre mon match','watch','','primary'):m&&!m.result&&!S.offseason?(o.matchReady[m.id]?.[S.user]?btn('Prêt pour le match · attente de l’adversaire','online-play','','primary',true):btn('Jouer mon match','online-play',`data-id="${m.id}"`,'primary',blocked||!!MP.member(S,S.user)?.delegated)):'';
 if(ON.host)action+=btn(MP.needsDayConfirmation(S)?onlineTransitionLabel():'Passer une journée','online-next','','primary',blocked||!MP.canAdvance(S,ON.presence));
 return action;
}
function onlineTransitionLabel(){return S.offseason?(S.offseason.stage==='awards'?'Passer au développement':'Commencer la nouvelle saison'):S.day===35?'Commencer les séries':'Ouvrir l’intersaison';}
function timeVoteLabel(v){return v.kind==='day'?(S.offseason?'passer à la prochaine étape de l’intersaison':'avancer d’une journée'):'simuler la période jusqu’au '+shortDate(v.day);}
function onlinePanel(){if(!isOnline()||S.online.phase==='lobby')return '';const o=S.online,me=MP.member(S,S.user),v=o.vote;return `<section class="online-bar"><div class="online-status"><b>Multijoueur · ${o.members.length}/6</b><span id="connection-status">${ON.presence.includes('t0')?'Session connectée':'En attente du retour de l’hôte…'}</span>${btn('Salon et invitations','online-room','','small')}</div><div class="online-members">${o.members.map(m=>`<span><b>${esc(m.name)}</b><small>${m.teamId==='t0'?'Hôte · ':''}${!ON.presence.includes(m.teamId)?'Absent':MP.liveFor(S,m.teamId)?'En match':m.delegated?'IA autorisée':'Connecté'}</small></span>`).join('')}</div><div class="actions">${onlineDayAction()}${btn(me?.delegated?'Reprendre mon équipe':'Autoriser l’IA en mon absence','online-delegate','','',!!S.live||!!v)}</div><p class="online-day-note">L’hôte propose le passage du temps. Tous les participants doivent accepter.</p>${o.timeNotice?`<p role="alert" class="notice">${esc(o.timeNotice.message)}</p>`:''}${v?`<div class="online-vote" role="status"><strong>${v.running?'Passage du temps approuvé…':'Demande : '+timeVoteLabel(v)}</strong><p>${Object.keys(v.approvals).length}/${o.members.length} accords</p>${ON.host?btn('Annuler la demande','online-cancel-vote'):''}</div>`:''}</section>`;}
function timeVoteDialog(){const v=S?.online?.vote;if(!v||v.running||v.approvals[S.user])return '';return `<div class="time-vote-overlay"><section class="time-vote-dialog" role="dialog" aria-modal="true" aria-labelledby="time-vote-title"><h2 id="time-vote-title">Passage du temps</h2><p>L’hôte propose de ${esc(timeVoteLabel(v))}.</p><p>${v.kind==='day'?'Les matchs non joués de cette journée seront simulés.':'Les matchs seront simulés jusqu’à la fin de la période ou la prochaine décision obligatoire.'}</p><div class="actions">${btn('Accepter','online-yes','','primary')}${btn('Refuser','online-no')}</div></section></div>`;}
function onlinePage(){
 if(ON.running&&S?.online){const o=S.online,me=MP.member(S,S.user);if(o.phase==='lobby'&&!me)return onlineJoinForm();return title(o.phase==='lobby'?'Salon de départ':'Salon de la ligue')+`<p class="notice">${o.phase==='lobby'?'Invitez vos amis avant de lancer le repêchage. Les places non occupées seront des équipes NPC.':'Participants fixés au lancement. Chacun retrouve son équipe grâce à son invitation personnelle.'}</p><div class="online-roster">${o.members.map(m=>panel(teamMark(E.team(S,m.teamId)),`<strong>${esc(m.name)}</strong><p>${m.teamId==='t0'?'Hôte · ':''}${ON.presence.includes(m.teamId)?'Connecté':'Absent'}</p>${ON.host&&m.teamId!=='t0'?btn('Copier son invitation','online-invite',`data-team="${m.teamId}"`):''}`)).join('')}</div>${ON.host?`<div class="actions space">${o.phase==='lobby'?['t1','t2','t3','t4','t5'].filter(id=>!MP.member(S,id)).map((id,i)=>btn('Inviter un ami · place '+(Number(id.slice(1))+1),'online-invite',`data-team="${id}"`)).join('')+btn('Lancer le repêchage','online-launch','','primary',!MP.allPresent(S,ON.presence)):btn('Exporter la sauvegarde','export')}</div>`:''}${o.phase==='playing'?btn('Retour au jeu','online-back','','primary'):''}<p class="muted">La sauvegarde complète reste dans le navigateur de l’hôte. Conservez votre lien personnel pour retrouver votre place.</p>${btn('Quitter le salon','quit','','quiet')}`;}
 return title('Jouer en ligne')+`<div class="tabs">${btn('Créer une ligue','online-create-tab','',''+(onlineView==='create'?'selected':''))}${btn('Rejoindre des amis','online-join-tab','',''+(onlineView==='join'?'selected':''))}</div>${onlineError?`<p class="notice" role="alert">${esc(onlineError)}</p>`:''}${onlineConnecting?'<p role="status">Connexion au salon…</p>':onlineView==='join'?`<form id="online-invite-form" class="panel panel-body"><label>Invitation personnelle<input name="invitation" type="url" required placeholder="Collez le lien envoyé par l’hôte"></label><button class="btn primary">Rejoindre le salon</button></form>`:panel('Votre ligue privée',`<form id="online-create-form"><label>Votre pseudo<input name="manager" maxlength="40" value="Manager" required></label><label>Nom de l’équipe<input name="team" maxlength="40" value="${esc(E.logoById(selectedLogo).teamName)}" required></label>${logoPicker()}<p>6 équipes · jusqu’à 6 joueurs · repêchage initial de 8 joueurs par équipe · aucune limite de temps.</p><button class="btn primary">Créer le salon</button></form>`)}`;
}
function onlineJoinForm(){const used=S.online.members.map(m=>E.team(S,m.teamId).logo),available=E.LOGOS.filter(l=>!used.includes(l.id));return title('Rejoindre la ligue')+panel('Choisissez votre équipe',`<form id="online-join-form"><label>Votre pseudo<input name="manager" maxlength="40" required></label><label>Logo et nom de l’équipe<select name="logo">${available.map(l=>`<option value="${l.id}">${esc(l.teamName)}</option>`).join('')}</select></label><p>Les logos déjà choisis sont réservés à leurs propriétaires.</p><button class="btn primary">Confirmer mon équipe</button></form>`);}
async function openOnlineSave(state){onlineError='';onlineConnecting=true;S=null;route='online';render();try{await ON.openHost(state);}catch(e){onlineError=e.message;ON.stop();S=MP.project(state,'t0');route='online';notify(e.message,true);}finally{onlineConnecting=false;render();}}
async function joinOnline(invite){onlineError='';onlineConnecting=true;S=null;route='online';render();try{await ON.join(invite);try{localStorage.setItem('slimball.invitation.'+invite.room,JSON.stringify(invite));}catch{}}catch(e){ON.stop();onlineError=e.message;S=null;}finally{onlineConnecting=false;render();}}
function onlineDecorate(){if(!S?.online)return;for(const action of ['draft-next','draft-until-user','draft-auto','continue-free'])document.querySelectorAll(`[data-action="${action}"]`).forEach(el=>el.remove());for(const action of ['next','offseason-next'])document.querySelectorAll(`[data-action="${action}"]`).forEach(el=>{if(!ON.host)el.remove();else{el.dataset.action='online-next';el.disabled=!!S.online.vote||!MP.canAdvance(S,ON.presence);}});document.querySelectorAll('[data-action="month"]').forEach(el=>{if(!ON.host){el.remove();return;}el.textContent='Simuler une période';el.disabled=!ON.host||!!S.online.vote||!!S.draft||!!S.offseason||Object.keys(S.online.lives).length>0;});
 if(!ON.host){document.querySelectorAll('[data-action="save"],[data-action="export"],[data-action="delete"],[data-action="backup"],#import-file').forEach(el=>{el.disabled=true;});const el=document.querySelector('#save-status');if(el)el.textContent='Sauvegarde chez l’hôte';}
 const c=S.live&&S.online.controls[S.live.id],mine=S.live&&(E.managed(S,S.live.home)?S.live.home:E.managed(S,S.live.away)?S.live.away:'t0')===S.user;
 if(c){for(const action of ['play-toggle','play-step','play-finish'])document.querySelectorAll(`[data-action="${action}"]`).forEach(el=>{el.disabled=!mine||!ON.presence.includes('t0')||[S.live.away,S.live.home].some(id=>E.managed(S,id)&&!ON.presence.includes(id));if(action==='play-toggle')el.textContent=c.playing?'Pause':'Lecture';if(action==='play-finish'&&[S.live.away,S.live.home].every(id=>E.managed(S,id)))el.remove();});const speed=document.querySelector('#play-speed');if(speed){speed.value=c.speed;speed.disabled=!mine;}const controls=document.querySelector('.field-wrap .actions');if(controls){if(!mine)controls.insertAdjacentHTML('beforeend',btn('Demander une pause','online-pause'));if(c.pauseRequested)controls.insertAdjacentHTML('beforeend','<span role="status">L’adversaire demande une pause.</span>');}}
 for(const action of ['simulate','pregame-simulate','pregame-watch'])document.querySelectorAll(`[data-action="${action}"]`).forEach(el=>{const m=S.schedule.find(m=>m.id===el.dataset.id);if(m&&[m.away,m.home].every(id=>E.managed(S,id)))el.textContent=S.online.matchReady[m.id]?.[S.user]?'Prêt · attente de l’adversaire':'Prêt pour le match';});
}
// Capture game-changing UI actions. The solo handlers never mutate online projections.
document.addEventListener('click',async ev=>{
 const el=ev.target.closest('[data-action]');if(!el||el.disabled)return;const d=el.dataset,action=d.action;
 const global=['online-menu','online-create-tab','online-join-tab'];
 const onlineActions=['online-room','online-back','online-invite','online-launch','online-play','online-ready','online-next','online-delegate','online-yes','online-no','online-cancel-vote','online-pause'];
 const gameActions=['rotation-next','auto-align','cut','sign','choose','draft-auto-one','draft-skip','draft-next','draft-until-user','draft-auto','pregame-watch','pregame-simulate','simulate','next','month','offseason-next','trade-accept','trade-refuse','offer-request','play-toggle','play-step','play-finish','quit','export','save','load','backup','continue-free'];
 if(!global.includes(action)&&!onlineActions.includes(action)&&!(isOnline()&&gameActions.includes(action)))return;
 if(['play-toggle','play-step'].includes(action)&&!S?.live)return;
 ev.preventDefault();ev.stopImmediatePropagation();
 try{
 if(action==='online-menu'){S=null;onlineView='create';navigate('online');return;}
 if(action==='online-create-tab'||action==='online-join-tab'){onlineView=action==='online-create-tab'?'create':'join';render();return;}
 if(action==='online-room'){navigate('online');return;}if(action==='online-back'){navigate(S.draft?'draft':'dashboard');return;}
 if(action==='online-invite'){const link=ON.invitation(d.team);try{await navigator.clipboard.writeText(link);notify('Invitation copiée. Envoyez ce lien à ce participant seulement.');}catch{modal.innerHTML=`<h2>Invitation personnelle</h2><input readonly value="${esc(link)}">${btn('Fermer','close')}`;modal.showModal();}return;}
 if(action==='online-launch'){confirmBox('Fixer les participants et commencer le repêchage ?',()=>sendOnline('launch'));return;}
 if(action==='online-play'){navigate('prematch',{id:d.id});return;}
 if(action==='online-ready'){await sendOnline('ready',{day:MP.dayKey(S),value:!S.online.ready[S.user]});return;}
 if(action==='online-next'||action==='next'||action==='offseason-next'){if(S.offseason&&S.offseason.stage!=='awards')confirmBox('Terminer la saison et ouvrir le prochain repêchage ?',()=>sendOnline('next'));else if(MP.needsDayConfirmation(S))confirmBox(onlineTransitionLabel()+' ?',()=>sendOnline('next'));else await sendOnline('next');return;}
 if(action==='online-delegate'){const delegated=MP.member(S,S.user).delegated;confirmBox(delegated?'Reprendre le contrôle de votre équipe ?':'Autoriser l’IA à gérer votre équipe et jouer vos matchs en votre absence ?',()=>sendOnline('delegate',{value:!delegated}));return;}
 if(action==='online-yes'||action==='online-no'){await sendOnline('vote',{vote:S.online.vote.id,accept:action==='online-yes'});return;}
 if(action==='online-cancel-vote'){await sendOnline('vote-cancel');return;}
 if(action==='month'){confirmBox('Proposer à tous les joueurs de simuler la période, y compris les matchs entre humains ?',()=>sendOnline('vote-propose'));return;}
 if(action==='rotation-next'){await sendOnline('rotation-next',{player:d.id});return;}
 if(action==='auto-align'){await sendOnline('align');return;}
 if(action==='cut'){confirmBox(t('confirm_cut'),()=>sendOnline('cut',{player:d.id}));return;}
 if(action==='sign'||action==='choose'){const type=action==='choose'?'draft':'sign';if(E.team(S).roster.length<8)await sendOnline(type,{player:d.id});else replacement(d.id,action==='choose');return;}
 if(action==='draft-skip'){await sendOnline('draft',{skip:true});return;}
 if(action==='draft-auto-one'){await sendOnline('draft',{auto:true});return;}
 if(['draft-next','draft-until-user','draft-auto'].includes(action))return;
 if(['pregame-watch','pregame-simulate','simulate'].includes(action)){const m=S.schedule.find(m=>m.id===d.id);if(!m||![m.away,m.home].includes(S.user))throw Error('Ce match appartient à une autre équipe.');const quick=action!=='pregame-watch'&&![m.away,m.home].every(id=>E.managed(S,id));confirmBox(quick?'Simuler votre match avec votre alignement actuel ?':'Confirmer votre alignement et vous déclarer prêt pour le match ?',()=>sendOnline('match-ready',{match:d.id,quick}));return;}
 if(['play-toggle','play-step','play-finish','online-pause'].includes(action)){await sendOnline('control',{match:S.live.id,action:{'play-toggle':'toggle','play-step':'step','play-finish':'finish','online-pause':'request-pause'}[action]});return;}
 if(action==='trade-accept'){confirmBox('Accepter cet échange ?',()=>sendOnline('accept',{trade:d.id}));return;}
 if(action==='trade-refuse'){await sendOnline('refuse',{trade:d.id});return;}
 if(action==='offer-request'){await sendOnline('offer');return;}
 if(action==='save'){if(ON.host){await ON.save(ON.state);notify(t('saved'));}return;}
 if(action==='export'){if(ON.host)Store.download(ON.state);return;}
 if(action==='quit'){confirmBox(ON.host?'Sauvegarder et fermer la session ? Les invités attendront votre retour.':'Quitter le salon ? Votre équipe restera réservée.',async()=>{if(ON.host)await ON.save(ON.state);await ON.leave();S=null;history.replaceState(null,'',location.pathname+location.search);navigate('menu');});return;}
 if(action==='load'||action==='backup')notify('Quittez le salon avant de charger une autre partie.',true);
 }catch(e){notify(e.message,true);}
},true);
document.addEventListener('submit',async ev=>{const f=ev.target,id=f.getAttribute('id')||'';if(!id.startsWith('online-')&&!(isOnline()&&['replace-form','trade-form','rotation-form'].includes(id)))return;ev.preventDefault();ev.stopImmediatePropagation();const d=new FormData(f);try{
 if(id==='online-create-form'){await openOnlineSave(MP.createLeague(d.get('team').trim(),d.get('manager').trim(),d.get('logo')||selectedLogo));}
 if(id==='online-invite-form'){const u=new URL(d.get('invitation'));const v=JSON.parse(new URLSearchParams(u.hash.slice(1)).get('online'));await joinOnline(v);}
 if(id==='online-join-form'){await sendOnline('join',{name:d.get('manager'),logo:d.get('logo')});}
 if(id==='replace-form'){await sendOnline(d.get('draft')==='true'?'draft':'sign',{player:d.get('id'),cut:d.get('cut')});modal.close();}
 if(id==='rotation-form'){await sendOnline('rotation',{players:d.getAll('pitcher').filter(Boolean)});}
 if(id==='trade-form'){await sendOnline('propose',{to:d.get('to'),offered:d.getAll('offered'),asked:d.getAll('asked'),pay:Number(d.get('pay')),receive:Number(d.get('receive'))});navigate('trades');}
 }catch(e){notify(e.message,true);}},true);
document.addEventListener('change',ev=>{if(!isOnline())return;const el=ev.target;if(el.id==='auto-toggle'||el.id==='play-speed'&&S.live){ev.stopImmediatePropagation();if(el.id==='auto-toggle')sendOnline('auto',{value:el.checked});else sendOnline('control',{match:S.live.id,action:'speed',speed:Number(el.value)});}},true);

render();
if(onlineInvite)joinOnline(onlineInvite);
Store.list().then(x=>{savedGames=x;if(!S)render();}).catch(()=>{});

let moveSource=null,touchMove=null,ignoreHandleClick=false;
function clearMove(){moveSource=null;document.querySelectorAll?.('[data-move-id]').forEach(el=>{el.classList.remove('move-selected','move-over');el.querySelector('.move-handle')?.setAttribute('aria-pressed','false');});}
function selectMove(el){clearMove();moveSource={id:el.dataset.moveId,kind:el.dataset.moveKind};el.classList.add('move-selected');el.querySelector('.move-handle')?.setAttribute('aria-pressed','true');}
function dropMove(el){const from=moveSource;clearMove();if(!from||!el||from.id===el.dataset.moveId)return;if(route!=='team'||archiveId||locked()||(params.id&&params.id!==S.user))return;if(S.online)sendOnline('swap',{from:from.id,to:el.dataset.moveId,kind:el.dataset.moveKind==='offense'?'offense':'defense'});else change(()=>E.swap(S,from.id,el.dataset.moveId,el.dataset.moveKind==='offense'?'offense':'defense'));}
document.addEventListener('dragstart',ev=>{if(touchMove){ev.preventDefault();return;}const el=ev.target.closest('[data-move-id]');if(!el)return;selectMove(el);ev.dataTransfer.setData('text/plain',el.dataset.moveId);ev.dataTransfer.effectAllowed='move';});
document.addEventListener('dragover',ev=>{const el=ev.target.closest('[data-move-id]');if(!el||!moveSource)return;ev.preventDefault();ev.dataTransfer.dropEffect='move';});
document.addEventListener('drop',ev=>{const el=ev.target.closest('[data-move-id]');if(!el||!moveSource)return;ev.preventDefault();dropMove(el);});
document.addEventListener('dragend',clearMove);
document.addEventListener('click',ev=>{if(!ev.target.closest('.move-handle'))return;ev.preventDefault();if(ignoreHandleClick){ignoreHandleClick=false;return;}const el=ev.target.closest('[data-move-id]');if(moveSource)dropMove(el);else selectMove(el);});
// Pointer dragging works directly on the portrait button with mouse, touch or pen.
// Keep native card dragging as a fallback; do not let it interrupt a portrait gesture.
let moveGhost=null;
function endPointerMove(){touchMove=null;moveGhost?.remove();moveGhost=null;}
function suppressMoveClick(){ignoreHandleClick=true;setTimeout(()=>ignoreHandleClick=false,0);}
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){if(touchMove?.moved)suppressMoveClick();endPointerMove();clearMove();}});
window.addEventListener('blur',()=>{endPointerMove();clearMove();});
document.addEventListener('pointerdown',ev=>{
 const handle=ev.target.closest('.move-handle'),el=handle?.closest('[data-move-id]');
 if(!el||ev.button!==0||ev.isPrimary===false||route!=='team'||archiveId||locked()||(params.id&&params.id!==S.user))return;
 touchMove={x:ev.clientX,y:ev.clientY,el,handle,pointerId:ev.pointerId,moved:false};
 handle.setPointerCapture?.(ev.pointerId);
});
document.addEventListener('pointermove',ev=>{
 if(!touchMove||ev.pointerId!==touchMove.pointerId)return;
 if(!touchMove.moved&&Math.hypot(ev.clientX-touchMove.x,ev.clientY-touchMove.y)<=8)return;
 if(!touchMove.moved){
  selectMove(touchMove.el);touchMove.moved=true;
  moveGhost=touchMove.handle.cloneNode?.(true);
  if(moveGhost){moveGhost.className='move-handle move-ghost';moveGhost.setAttribute('aria-hidden','true');moveGhost.tabIndex=-1;document.body.appendChild(moveGhost);}
 }
 ev.preventDefault();
 if(moveGhost){moveGhost.style.left=(ev.clientX+14)+'px';moveGhost.style.top=(ev.clientY+14)+'px';}
 document.querySelectorAll?.('[data-move-id]').forEach(el=>el.classList.remove('move-over'));
 const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-move-id]');
 if(target&&target.dataset.moveId!==touchMove.el.dataset.moveId)target.classList.add('move-over');
},{passive:false});
document.addEventListener('pointerup',ev=>{
 if(!touchMove||ev.pointerId!==touchMove.pointerId)return;
 const moved=touchMove.moved;endPointerMove();
 if(moved){suppressMoveClick();dropMove(document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-move-id]'));}
});
document.addEventListener('pointercancel',ev=>{if(touchMove&&ev.pointerId===touchMove.pointerId){endPointerMove();clearMove();}});

function statsScopeTabs(){if(!['team','profile','leaders'].includes(route))return '';return `<div class="tabs" aria-label="${t('stats')}">${btn(tr('Saison régulière','Regular season','Temporada regular'),'stats-scope','data-scope="regular"',statScope==='regular'?'selected':'')}${btn(t('playoffs'),'stats-scope','data-scope="playoffs"',statScope==='playoffs'?'selected':'')}</div>`;}
function playoffPage(){const src=dataSource(),po=src.playoffs;if(!po)return title(t('playoffs'))+panel(t('winter'),`<p>${tr('Les quatre premières équipes se qualifieront à la fin de la saison régulière. Demi-finales : 1 contre 4 et 2 contre 3, au meilleur de 3. Finale au meilleur de 5.','The top four qualify after the regular season. Best-of-three semifinals: 1–4 and 2–3. Best-of-five final.','Los cuatro primeros se clasifican. Semifinales al mejor de tres: 1–4 y 2–3. Final al mejor de cinco.')}</p>`);
 return title(t('playoffs'),badge(t('winter')))+(po.winner?`<div class="champion-banner"><span>★</span><div><small>${t('champion')}</small><h2>${teamMark(E.team(src,po.winner))}</h2></div></div>`:'')+`<div class="playoff-bracket">${po.series.map(series=>panel(series.id==='final'?tr('Finale · 3 victoires','Final · 3 wins','Final · 3 victorias'):tr('Demi-finale · 2 victoires','Semifinal · 2 wins','Semifinal · 2 victorias'),`<div class="series-teams">${series.teams.map((id,i)=>`<div class="series-team ${series.winner===id?'series-winner':''}"><span>#${po.seeds.indexOf(id)+1}</span>${go(teamMark(E.team(src,id)),'team',`data-id="${id}"`)}<strong>${series.wins[i]}</strong></div>`).join('')}</div><ol class="series-games">${series.games.map((id,i)=>{const m=src.schedule.find(x=>x.id===id);return `<li><span>${tr('Match','Game','Partido')} ${i+1} · ${esc(E.team(src,m.home).name)} ${tr('reçoit','hosts','recibe')}</span>${m.result?go(m.result.score.join(' — '),'match',`data-id="${id}"`):!archiveId&&m.day===S.day?btn(t('watch'),'watch-start',`data-id="${id}"`,'primary',locked()):badge(shortDate(m.day))}</li>`;}).join('')}</ol>${series.winner?`<p><b>${esc(E.team(src,series.winner).name)}</b> · ${tr('Série remportée','Series won','Serie ganada')}</p>`:''}`)).join('')}${po.series.length<3?panel(tr('Finale','Final','Final'),`<p>${tr('Les vainqueurs des demi-finales se rencontreront ici.','The semifinal winners will meet here.','Los ganadores de las semifinales se enfrentarán aquí.')}</p>`):''}</div>${!archiveId&&S.offseason?go(t('offseason'),'offseason','','primary'):!archiveId?go(t('back'),'dashboard'):''}`;}
function awardPresentation(src){
 const prizes=(src?.awards||[]).filter(a=>a.type!=='award_progress'),key=S.id+':'+S.season+':'+S.user,index=awardCursor[key]||0,a=prizes[index];
 if(!a)return awardCards(src)+btn(tr('Revoir la cérémonie','Replay ceremony','Repetir ceremonia'),'award-replay');
 const p=src.players[a.id]||S.players[a.id],tm=src.teams.find(t=>t.id===a.teamId),post=a.type==='award_playoffs',scored=post?{...p,stats:p.playoffStats||E.blankStats()}:p;
 const runners=(a.podium||[]).slice(1).map(q=>{const p=src.players[q.id]||S.players[q.id],tm=src.teams.find(t=>t.id===q.teamId);return `<article class="award-runner"><b>#${q.rank}</b>${portrait(p,'medium-portrait',tm||null,src)}${playerLink(p,'',false,tm||null)}<span>${n(q.score,a.type==='avg'?3:1)} ${tr('indice','index','índice')}</span></article>`;}).join('');
 return `<section class="award-presentation" aria-live="polite"><div class="actions">${btn(tr('Continuer','Continue','Continuar'),'award-next','','primary')}${btn(tr('Passer la cérémonie · tous les trophées','Skip ceremony · all awards','Omitir ceremonia · todos los premios'),'award-skip')}</div><small>${index+1} / ${prizes.length} · ${t('season')} ${src.season}</small><h2>★ ${t(a.type)}</h2><div class="award-winner">${portrait(p,'large-portrait',tm||null,src)}<div><h3>${playerLink(p,'',false,tm||null)}</h3><p>${esc(tm?.name||t('free'))}</p><b>${n(a.score,a.type==='avg'?3:1)} ${tr('indice','index','índice')}</b><p>${p.age} ${tr('ans','years','años')} · ${badge(p.grade)}${helpMark('grade')} · ${formName(p.form)}${helpMark('form')}</p><p>${E.ATTR.map(k=>`${colLabel(k)} <b>${p.base[k]}</b>`).join(' · ')} · ${colLabel('value')} ${n(E.tradeValue(p,src))}</p></div></div><h3>${post?t('playoffs'):tr('Statistiques de la saison','Season statistics','Estadísticas de temporada')}</h3><div class="stats-grid">${statList(scored,['avg','ab','hits','hr','rbi','bb','so'])}${statList(scored,['balls','catchOuts','throwOuts','errors','def'])}${statList(scored,['pitchSO','pitchBB','pitchOuts','era','whip'])}</div><div class="award-runners">${runners}</div></section>`;
}
function offseasonPage(){
 const o=S.offseason;if(!o)return title(t('offseason'))+panel(t('offseason'),`<p>${tr('L’intersaison commence après les séries hivernales.','Offseason begins after the playoffs.','La entretemporada comienza tras las eliminatorias.')}</p>`);
 const names=[tr('Récompenses','Awards','Premios'),tr('Progression et retraites','Development and retirements','Progresión y retiradas')],index=o.stage==='awards'?0:1,src=S.archives.find(a=>a.season===S.season),prizes=(src?.awards||[]).filter(a=>a.type!=='award_progress'),ceremonyDone=(awardCursor[S.id+':'+S.season+':'+S.user]||0)>=prizes.length;
 const content=index===0?awardPresentation(src):seasonPage(true);
 return title(t('offseason'))+`<ol class="offseason-steps">${names.map((name,i)=>`<li class="${i===index?'current':i<index?'complete':''}">${i+1} · ${name}</li>`).join('')}</ol><div class="actions offseason-continue">${S.careerResult?`<p>${t(S.careerResult)}</p>${btn(t('continue_free'),'continue-free','','primary')}`:''}${index===1||ceremonyDone?btn(index===1?tr('Terminer la saison et ouvrir le repêchage','End season and open draft','Terminar temporada y abrir draft'):names[1],'offseason-next','','primary',index===1&&!!S.careerResult):''}</div>${content}`;
}

function journalText(e){const draftInfo=e.key==='drafted'&&e.round?` · ${t('round')} ${e.round} · #${e.pick} ${tr('au total','overall','global')}`:'';return draftInfo+t(e.key,{...e.args,...(e.args?.prize?{prize:t(e.args.prize)}:{}),...(e.args?.stat?{stat:t(e.args.stat)}:{}),...(e.args?.type?{type:t('obj_'+e.args.type)}:{})});}
function awardCards(src){if(!src)return '';const prizes=src.awards??Object.values(src.players).flatMap(p=>p.awards.filter(a=>a.season===src.season&&a.rank===1&&a.type!=='champion').map(a=>({...a,id:p.id,name:p.name,teamId:src.teams.find(t=>t.roster.includes(p.id))?.id||null,score:E.stats(p)[a.type]||0})));return panel(tr('Cérémonie des prix','Awards ceremony','Ceremonia de premios'),`<p class="muted">${tr('Saison régulière pour les prix annuels; éliminatoires pour le MVP des séries. La progression est récompensée après le développement d’intersaison.','Annual awards use regular-season results; playoff MVP uses postseason results. Most improved is awarded after offseason development.','Los premios anuales usan la temporada regular; el MVP de eliminatorias usa la postemporada. La progresión se premia después del desarrollo.')}</p><div class="award-grid">${prizes.map(a=>{const p=src.players[a.id]||S.players[a.id],tm=src.teams.find(t=>t.id===a.teamId);return `<article class="award-card"><span class="award-star" aria-hidden="true">★</span><h3>${t(a.type)}</h3>${portrait(p,'medium-portrait',tm||null,src)}<div class="award-player">${playerLink(p,'',false,tm||null)}</div><small>${esc(tm?.name||t('free'))} · S${a.season}</small><b>${a.type==='award_progress'?'+':''}${n(a.score,a.type==='avg'?3:['hr','rbi','award_progress'].includes(a.type)?0:1)} ${a.type==='award_progress'?tr('points d’attributs','attribute points','puntos de atributos'):['avg','hr','rbi'].includes(a.type)?t(a.type):tr('indice','index','índice')}</b></article>`;}).join('')||`<p>${tr('Aucun prix individuel enregistré pour cette saison.','No individual awards recorded for this season.','No hay premios individuales registrados para esta temporada.')}</p>`}</div>${src.season===1?`<p>${tr('Le prix de recrue de l’année débute en saison 2.','Rookie of the year begins in season 2.','El premio al novato del año comienza en la temporada 2.')}</p>`:''}<details><summary>${tr('Critères et admissibilité','Criteria and eligibility','Criterios y elegibilidad')}</summary><p>${tr('Bâton d’or : buts sur coups sûrs + 0,7 BB + 0,5 R + 0,6 RBI − 0,3 SO. Gant d’or : retraits en réception et au lancer − 2 erreurs. Lanceur : 0,4 retraits lancés + SO − 1,5 points mérités − 0,5 coups sûrs concédés − 0,5 BB. MVP : attaque + moitié de la défense + moitié du score de lancer positif.','Golden Bat: total bases + 0.7 BB + 0.5 R + 0.6 RBI − 0.3 SO. Glove: catches and throwing outs − 2 errors. Pitcher: 0.4 pitching outs + SO − 1.5 ER − 0.5 hits allowed − 0.5 BB. MVP: offense + half defense + half positive pitching score.','Bate: bases totales + 0,7 BB + 0,5 R + 0,6 RBI − 0,3 SO. Guante: outs defensivos − 2 errores. Lanzador: 0,4 outs lanzados + SO − 1,5 ER − 0,5 hits permitidos − 0,5 BB. MVP: ataque + mitad de defensa + mitad del índice positivo de lanzamiento.')}</p><p>${tr('Minimums : 30 présences officielles pour le Bâton d’or et la moyenne; 20 occasions défensives pour le Gant d’or; 18 manches lancées pour le prix de lanceur. MVP et recrue : 30 présences au bâton (BB inclus) ou 18 manches lancées. MVP des séries : 6 présences ou 3 manches. Recrue : aucune participation lors d’une saison antérieure. Progression : gain net positif d’attributs et participation à la saison. Égalités : volume de participation, puis identifiant stable; progression : identifiant stable. Un prix sans candidat admissible n’est pas attribué.','Minimums: 30 AB for Bat and average; 20 defensive chances for Glove; 18 innings for Pitcher. MVP and rookie: 30 PA or 18 innings. Playoff MVP: 6 PA or 3 innings. Rookie: no prior season participation. Improvement: positive net attribute gain and season participation. Ties: participation, then stable ID; improvement: stable ID. Awards without eligible candidates are not assigned.','Mínimos: 30 AB para bate y promedio; 20 oportunidades para guante; 18 entradas para lanzador. MVP y novato: 30 PA o 18 entradas. MVP de eliminatorias: 6 PA o 3 entradas. Novato: sin participación previa. Progresión: mejora neta positiva y participación. Empates: participación y luego ID estable; progresión: ID estable. Sin candidatos elegibles no se otorga el premio.')}</p></details>`);}
function leaguePage(){return title(t('league'))+clubCards()+panel(tr('Les nouvelles du terrain','News from the field','Noticias del campo'),events(S.leagueNews||[]));}
function preMatchPage(){const r=E.preMatchReport(S,params.id);if(!r||archiveId)return title(t('prematch'))+empty(t('match_unavailable'));const m=r.match;return title(t('prematch'),go(t('back'),'dashboard'))+parkView(E.team(S,m.home),'briefing-park')+`<p class="notice">${tr('Les alignements automatiques sont prévus selon l’énergie actuelle. Les conseils ne changent pas votre équipe. Revenez sur ce rapport après vos ajustements.','Automatic lineups are projected from current energy. Advice does not change your team. Reopen this report after making adjustments.','Las alineaciones automáticas se prevén según la energía actual. Los consejos no cambian tu equipo. Regresa al informe tras ajustar.')}</p><div class="actions">${go(tr('Modifier l’alignement','Edit lineup','Editar alineación'),'team',`data-id="${S.user}"`)}${btn(tr('Lancer la partie','Start game','Iniciar partido'),'pregame-watch',`data-id="${m.id}"`,'primary',locked())}${btn(t('simulate'),'pregame-simulate',`data-id="${m.id}"`,'',locked())}</div><div class="two-col">${r.teams.map(x=>panel(teamMark(x.team),`<p>#${x.rank} · ${x.team.w} ${t('wins')} / ${x.team.l} ${t('losses')}</p><p>${tr('Cinq derniers matchs','Last five games','Últimos cinco partidos')} : ${x.form.map(g=>badge(g.win?tr('V','W','V'):tr('D','L','D'))).join(' ')||'—'}</p><h3>${tr('Lanceur prévu','Projected pitcher','Lanzador previsto')}</h3>${playerLink(x.pitcher,'',true,x.team)}<p>${t('energy')} ${x.pitcher.energy}/100 · Thr ${x.pitcher.base.throw}/10</p><h3>${tr('Frappeurs à surveiller','Hitters to watch','Bateadores a seguir')}</h3>${x.hitters.map(p=>`${playerLink(p,'',true,x.team)}<small>${p.stats.hr} HR · ${n(p.stats.ab?p.stats.hits/p.stats.ab:0,3)} AVG · Con ${p.base.contact} / Pow ${p.base.power}</small>`).join('')}<p>${tr('Réception moyenne des titulaires','Average starting fielding skill','Recepción media de titulares')} : ${n(x.defense,1)}/10</p>`)).join('')}</div>${panel(tr('Conseils pour ce match','Game advice','Consejos para el partido'),r.tips.map(e=>`<p>${esc(journalText(e))}</p>`).join('')||tr('Match observé entre deux clubs NPC.','Spectator game between NPC clubs.','Partido entre clubes NPC.'))}${panel(tr('Derniers duels','Recent head-to-head games','Últimos enfrentamientos'),r.h2h.map(g=>`<p>S${g.season} · ${esc(E.team(S,g.away).name)} ${g.result.score.join(' — ')} ${esc(E.team(S,g.home).name)}</p>`).join('')||tr('Premier affrontement enregistré.','First recorded meeting.','Primer enfrentamiento registrado.'))}`;}

function championshipBanner(){if(!S?.playoffs?.winner||S.presentation?.championSeen===S.season||S?.online&&onlineChampionSeen.has(S.id+':'+S.season))return '';stopPlay();const tm=E.team(S,S.playoffs.winner),final=S.playoffs.series.find(x=>x.id==='final'),opponent=final?.teams.find(id=>id!==tm.id);return `<div class="championship-overlay" role="dialog" aria-modal="true" aria-labelledby="champion-title"><section style="${themeTokens(tm.logo)}"><div class="champion-confetti" aria-hidden="true">${Array.from({length:18},(_,i)=>`<i style="left:${i*5.5}%;animation-delay:-${i*.17}s"></i>`).join('')}</div><div class="championship-trophy">${statIcon('champion')}</div>${teamMark(tm,'large-team')}<h1 id="champion-title">${tr('Champions !','Champions!','¡Campeones!')}</h1><p>${t('season')} ${S.season} · ${opponent?esc(E.team(S,opponent).name):''} · ${final?final.wins.join(' – '):''}</p>${btn(t('continue'),'champion-dismiss','','primary')}</section></div>`;}
function dynastyPage(){const d=dynastyReport(S),tm=E.team(S),won=S.careerResult==='won'||S.mode==='career'&&S.playoffs?.winner===S.user;const metric=(label,value)=>`<div><b>${value}</b><span>${label}</span></div>`;
 const card=(p,label,role)=>p?`<article class="dynasty-player"><h3>${label}</h3>${portrait(S.players[p.id]||{id:p.id},'medium-portrait',tm)}<strong>${esc(p.name)}</strong><p>${p.games} ${tr('matchs','games','partidos')} · ${role==='pitcher'?`${p.stats.pitchSO||0} SO · ${p.stats.pitchOuts?n(p.stats.earned*27/p.stats.pitchOuts,2):'—'} ERA`:role==='fielder'?`${(p.stats.catchOuts||0)+(p.stats.throwOuts||0)} ${tr('retraits','outs','outs')} · ${p.stats.errors||0} E`:`${statIcon('hr')}${p.stats.hr||0} HR · ${statIcon('avg')}${n(p.stats.ab?p.stats.hits/p.stats.ab:0,3)} AVG`}</p></article>`:'';
 return title(won?tr('Carrière remportée !','Career won!','¡Carrera ganada!'):tr('Bilan de la dynastie','Dynasty report','Balance de la dinastía'))+`<div class="dynasty-header">${statIcon('champion')}${teamMark(tm,'large-team')}<p>${won?tr('Tu as atteint ton objectif : remporter le championnat. Voici le parcours de ton club.','You reached your goal: win the championship. Here is your club’s journey.','Lograste el objetivo: ganar el campeonato. Este es el recorrido de tu club.'):''}</p></div><div class="metrics dynasty-metrics">${metric(t('season'),d.seasons)}${metric(tr('Victoires – défaites','Wins – losses','Victorias – derrotas'),d.wins+' – '+d.losses)}${metric(tr('Victoires','Wins','Victorias'),n(d.wins+d.losses?100*d.wins/(d.wins+d.losses):0,1)+' %')}${metric(t('playoffs'),d.playoffs)}${metric(tr('Titres','Titles','Títulos'),d.titles)}</div><p>${tr('Saison la plus victorieuse','Season with most wins','Temporada con más victorias')} : ${d.bestSeason?'S'+d.bestSeason.season+' · '+d.bestSeason.w+' – '+d.bestSeason.l:'—'}</p><p class="muted">${tr('Statistiques accumulées avec ce club uniquement, saison régulière et séries comprises. Moyenne record : minimum 30 présences officielles au bâton.','Statistics accumulated with this club only, including regular season and playoffs. Average record: minimum 30 at-bats.','Estadísticas con este club, incluyendo temporada y eliminatorias. Récord de promedio: mínimo 30 turnos oficiales.')}</p>${d.missing?`<p class="notice">${tr('Certaines anciennes feuilles de match sont absentes : les totaux individuels sont partiels.','Some old match sheets are missing: individual totals are partial.','Faltan algunas actas antiguas: los totales individuales son parciales.')}</p>`:''}<div class="dynasty-stars">${card(d.stars.batter,tr('Frappeur marquant','Leading batter','Bateador destacado'))}${card(d.stars.pitcher,tr('Lanceur marquant','Leading pitcher','Lanzador destacado'),'pitcher')}${card(d.stars.fielder,tr('Défenseur marquant','Leading fielder','Defensor destacado'),'fielder')}${card(d.stars.loyal,tr('Pilier du club','Club mainstay','Pilar del club'))}</div>${panel(tr('Records du club','Club records','Récords del club'),Object.entries(d.records).map(([k,p])=>`<p>${statIcon(k)}<b>${t(k)}</b> : ${p?esc(p.name)+' · '+(k==='avg'?n(p.stats.hits/p.stats.ab,3):p.stats[k]||0):'—'}</p>`).join(''))}${panel(t('awards'),d.awards.map(a=>`<p>${statIcon('awards')}S${a.season} · ${esc(a.name||S.players[a.id]?.name)} · ${t(a.type)}</p>`).join('')||t('no_awards'))}<div class="actions">${go(t('archives'),'archives')}${won?btn(tr('Continuer en mode libre','Continue in free mode','Continuar en modo libre'),'continue-free','','primary'):go(t('dashboard'),'dashboard')}</div>${won?`<p>${tr('Le mode libre conserve ton club et son histoire. Les saisons continuent sans limite ni condition de fin de carrière.','Free mode keeps your club and its history. Seasons continue without a limit or career ending condition.','El modo libre conserva tu club e historia. Las temporadas continúan sin límite ni condición de final.')}</p>`:''}`;
}

document.addEventListener('keydown',ev=>{if(['Enter',' '].includes(ev.key)&&ev.target.matches?.('.stat-help')){ev.preventDefault();ev.target.click();}});

document.addEventListener('input',ev=>{if(ev.target.id==='wiki-search'){const pos=ev.target.selectionStart;wikiQuery=ev.target.value;render();const input=document.querySelector('#wiki-search');input.focus({preventScroll:true});if(pos!=null)input.setSelectionRange(pos,pos);}});

document.addEventListener('change',ev=>{const el=ev.target,id=el.dataset?.preferencePlayer;if(!id)return;const values=[...(E.team(S).positionPreferences?.[id]||['',''])];values[Number(el.dataset.preferenceIndex)]=el.value;if(isOnline())sendOnline('preferences',{player:id,preferences:values});else change(()=>E.setPositionPreferences(S,id,values));});
